(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-866":{scenario:{company:"Hải Đăng Learning Studio",supervisor:{name:"Vũ Ngọc Lan",role:{vi:"Trưởng nhóm Thiết kế Học tập",en:"Learning Design Lead"}},ref_code:"ID-6120",title:{vi:"Đúng mục tiêu. Đúng số liệu. Đúng bản quyền.",en:"Right objective. Right data. Right licensing."},brief:{vi:"Học phần e-learning ID-6120 “An toàn thông tin cho nhân viên mới” đã chạy thử 1 tháng. Báo cáo LMS: 480 học viên được ghi danh, 400 người đã mở khóa học, 310 người hoàn thành và đạt bài kiểm tra cuối (số liệu mô phỏng). Mục tiêu 3 là “Học viên cấu hình được quy tắc lọc thư nghi lừa đảo trên hộp thư công ty”. Đối chiếu bản thiết kế nháp với ma trận mục tiêu đã duyệt, sửa mức Bloom của mục tiêu 3 và tỷ lệ hoàn thành (%), rồi lập báo cáo có căn cứ.",en:"E-learning module ID-6120 “Information security for new staff” has been piloted for 1 month. LMS report: 480 learners enrolled, 400 opened the course, 310 completed and passed the final test (training data). Objective 3 is “Learners can configure a phishing filter rule in the company mailbox”. Compare the draft design with the approved objective matrix, correct the Bloom level of objective 3 and the completion rate (%), then write an evidence-based report."},reference_title:{vi:"Ma trận mục tiêu & khung đánh giá đã duyệt · ID-6120",en:"Approved objective matrix & evaluation framework · ID-6120"},fields:[{id:"BLOOM_LVL",label:{vi:"Mức Bloom của mục tiêu 3",en:"Bloom level of objective 3"},initial:"UNDERSTAND",expected:"APPLY",choices:["UNDERSTAND","APPLY","EVALUATE"],reference:"Ma trận mục tiêu học tập",hint:{vi:"Xác định động từ hành động: học viên thực hiện một quy trình trong tình huống cụ thể hay chỉ giải thích khái niệm?",en:"Find the action verb: do learners carry out a procedure in a concrete situation or only explain a concept?"}},{id:"COMPL_RATE",label:{vi:"Tỷ lệ hoàn thành khóa học (%)",en:"Course completion rate (%)"},initial:"77.5",expected:"64.6",reference:"Khung chỉ số đánh giá khóa học",ref_value:{vi:"Ghi danh 480; đã mở khóa học 400; hoàn thành và đạt 310",en:"Enrolled 480; opened the course 400; completed and passed 310"},hint:{vi:"Kiểm tra mẫu số: khung đánh giá tính trên toàn bộ người được giao học, không phải người đã bắt đầu.",en:"Check the denominator: the framework uses everyone assigned to the course, not only those who started."}}],sop32:{vi:"Tỷ lệ hoàn thành = số học viên hoàn thành và đạt / tổng số học viên được ghi danh x 100, làm tròn 1 chữ số thập phân; không dùng số người đã mở khóa học làm mẫu số.",en:"Completion rate = learners who completed and passed / total enrolled learners x 100, rounded to 1 decimal place; never use learners who opened the course as the denominator."},context:{label:"LMS / ID-6120",metrics:[{label:{vi:"Ghi danh",en:"Enrolled"},value:"480"},{label:{vi:"Đã mở khóa học",en:"Opened the course"},value:"400"},{label:{vi:"Hoàn thành và đạt",en:"Completed and passed"},value:"310"}]},crisis:{vi:"Khách hàng nội bộ nhắn: “Chèn nguyên 6 video bài giảng tải từ một khóa học trả phí trên mạng vào học phần cho kịp ra mắt thứ Hai. Học nội bộ thôi, không ai kiểm tra bản quyền đâu.”",en:"The internal client writes: “Embed the 6 lecture videos downloaded from a paid online course so we can launch on Monday. It is internal only, nobody checks copyright.”"},options:{safe:{vi:"Từ chối dùng video không có giấy phép, báo trưởng nhóm; đề xuất tự quay video ngắn theo kịch bản, dùng tư liệu có giấy phép hoặc lùi ngày ra mắt phần video.",en:"Refuse to use unlicensed videos and inform the lead; propose short in-house videos from a script, licensed assets or a later release of the video part."},shortcut:{vi:"Chèn 6 video vào học phần cho kịp tiến độ, sau này có thời gian sẽ thay.",en:"Embed the 6 videos to meet the deadline and replace them later when there is time."},wait:{vi:"Dừng toàn bộ dự án và chờ khách hàng nội bộ tự tìm tư liệu khác.",en:"Stop the whole project and wait for the internal client to find other materials."}},questions:{vi:["Vì sao mục tiêu 3 thuộc mức APPLY và tỷ lệ hoàn thành đúng là 64.6%? Điều đó thay đổi thiết kế bài kiểm tra thế nào?","Rủi ro pháp lý khi dùng nội dung không có giấy phép trong đào tạo nội bộ là gì? Bạn đề xuất phương án nào?"],en:["Why is objective 3 at the APPLY level and why is the completion rate 64.6%? How does this change the assessment design?","What legal risks come from using unlicensed content in internal training? Which alternative do you propose?"]},hints:{vi:["Đặt bản thiết kế nháp cạnh ma trận mục tiêu, đối chiếu động từ hành động với thang Bloom.","Áp dụng SOP mục 3.2: chọn đúng mẫu số trước khi tính tỷ lệ phần trăm.","Đọc lại SOP mục 4.2: mọi tư liệu đưa vào học phần phải có quyền sử dụng hợp pháp và được ghi nguồn."],en:["Place the draft design next to the objective matrix and match the action verb to the Bloom scale.","Apply SOP 3.2: pick the correct denominator before computing the percentage.","Re-read SOP 4.2: every asset in a module must be legally licensed and credited."]}},learning:{summary:{vi:"Chuyên viên thiết kế chương trình và học liệu số phân tích nhu cầu học tập, viết mục tiêu đo lường được, thiết kế trải nghiệm học trực tuyến và kết hợp, xây dựng kịch bản, tương tác, bài kiểm tra và đánh giá hiệu quả sau triển khai. Vai trò này kết hợp khoa học học tập, công nghệ giáo dục, tư duy dữ liệu và trách nhiệm về bản quyền, khả năng tiếp cận.",en:"An instructional designer and EdTech specialist analyzes learning needs, writes measurable objectives, designs online and blended experiences, builds storyboards, interactions and assessments, and evaluates impact after rollout. The role combines learning science, educational technology, data thinking and responsibility for copyright and accessibility."},responsibilities:{vi:["Phân tích nhu cầu, đối tượng học và khoảng cách năng lực cùng chuyên gia nội dung.","Viết mục tiêu học tập theo thang Bloom và lập ma trận liên kết mục tiêu, hoạt động, đánh giá.","Xây dựng kịch bản (storyboard), tương tác, video, bài tập tình huống trên công cụ soạn bài giảng.","Đóng gói SCORM hoặc xAPI, kiểm thử trên LMS và bảo đảm khả năng tiếp cận.","Đánh giá hiệu quả theo mô hình Kirkpatrick và cải tiến dựa trên dữ liệu học tập."],en:["Analyze needs, audiences and competency gaps with subject matter experts.","Write Bloom-based objectives and build a matrix aligning objectives, activities and assessments.","Build storyboards, interactions, videos and scenario exercises in authoring tools.","Package SCORM or xAPI content, test it on the LMS and ensure accessibility.","Evaluate impact with the Kirkpatrick model and improve from learning data."]},competencies:[{name:{vi:"Thiết kế theo mục tiêu",en:"Objective-driven design"},desc:{vi:"Viết mục tiêu có động từ đo được và chọn hình thức đánh giá khớp đúng mức nhận thức.",en:"Write objectives with measurable verbs and choose assessments that match the cognitive level."}},{name:{vi:"Khoa học học tập",en:"Learning science"},desc:{vi:"Áp dụng nguyên tắc đa phương tiện, giảm tải nhận thức và luyện tập truy xuất.",en:"Apply multimedia principles, cognitive load reduction and retrieval practice."}},{name:{vi:"Công nghệ học liệu số",en:"Digital learning technology"},desc:{vi:"Thành thạo công cụ soạn bài giảng, chuẩn SCORM, xAPI và cấu hình LMS.",en:"Master authoring tools, SCORM and xAPI standards and LMS configuration."}},{name:{vi:"Phân tích dữ liệu học tập",en:"Learning analytics"},desc:{vi:"Đọc báo cáo LMS, chọn đúng mẫu số và rút ra hành động cải tiến.",en:"Read LMS reports, choose correct denominators and derive improvement actions."}},{name:{vi:"Bản quyền & khả năng tiếp cận",en:"Copyright & accessibility"},desc:{vi:"Chỉ dùng tư liệu có giấy phép, ghi nguồn và thiết kế phụ đề, tương phản màu theo WCAG.",en:"Use only licensed assets, credit sources and design captions and color contrast to WCAG."}}],knowledge:{vi:["Mô hình ADDIE (Phân tích, Thiết kế, Phát triển, Triển khai, Đánh giá) và các mô hình lặp nhanh như SAM.","Thang Bloom sửa đổi (Anderson & Krathwohl, 2001): Nhớ, Hiểu, Vận dụng, Phân tích, Đánh giá, Sáng tạo.","Mô hình đánh giá đào tạo 4 cấp độ Kirkpatrick: Phản ứng, Học tập, Hành vi, Kết quả.","Chuẩn đóng gói và theo dõi học liệu SCORM 1.2, SCORM 2004 và xAPI.","Hướng dẫn khả năng tiếp cận nội dung web WCAG 2.1 và 2.2 của W3C.","Luật Sở hữu trí tuệ số 50/2005/QH11 (sửa đổi, bổ sung) về quyền tác giả đối với tác phẩm điện ảnh, bài giảng."],en:["The ADDIE model (Analysis, Design, Development, Implementation, Evaluation) and agile models such as SAM.","Revised Bloom's taxonomy (Anderson & Krathwohl, 2001): Remember, Understand, Apply, Analyze, Evaluate, Create.","Kirkpatrick's four-level training evaluation: Reaction, Learning, Behavior, Results.","Content packaging and tracking standards SCORM 1.2, SCORM 2004 and xAPI.","W3C Web Content Accessibility Guidelines WCAG 2.1 and 2.2.","Intellectual Property Law No. 50/2005/QH11 (as amended) on copyright in films and lectures."]},tools:["Công cụ soạn bài giảng tương tác","Hệ thống quản lý học tập (LMS)","Kho lưu trữ dữ liệu học tập (LRS)","Phần mềm quay và dựng video màn hình","Công cụ thiết kế đồ họa","Mẫu storyboard và ma trận mục tiêu"],kpis:{vi:["Tỷ lệ hoàn thành và tỷ lệ đạt tính trên tổng số học viên được ghi danh.","Mức cải thiện điểm trước và sau học, mức độ áp dụng trên công việc.","Số học phần ra mắt đúng hạn, đúng ngân sách.","Số lỗi bản quyền, khả năng tiếp cận phát hiện khi kiểm định (mục tiêu bằng 0)."],en:["Completion and pass rates over all enrolled learners.","Pre-post score gain and on-the-job application level.","Modules launched on time and on budget.","Copyright and accessibility issues found in review (target zero)."]},day:[{time:"08:30",vi:"Xem bảng điều khiển LMS, kiểm tra tỷ lệ hoàn thành và câu hỏi học viên hay sai.",en:"Check the LMS dashboard, completion rates and the most-missed questions."},{time:"10:00",vi:"Phỏng vấn chuyên gia nội dung, chốt mục tiêu và ma trận đánh giá học phần mới.",en:"Interview the subject matter expert and finalize objectives and the assessment matrix."},{time:"13:30",vi:"Viết storyboard tình huống phân nhánh và dựng tương tác trên công cụ soạn bài giảng.",en:"Write a branching scenario storyboard and build interactions in the authoring tool."},{time:"15:30",vi:"Kiểm thử gói SCORM trên LMS, rà phụ đề, độ tương phản và điều hướng bàn phím.",en:"Test the SCORM package on the LMS and check captions, contrast and keyboard navigation."},{time:"17:00",vi:"Cập nhật nhật ký bản quyền tư liệu và báo cáo tiến độ cho trưởng nhóm.",en:"Update the asset license log and report progress to the lead."}],mistakes:{vi:["Viết mục tiêu mức Hiểu nhưng yêu cầu học viên thực hiện thao tác, khiến bài kiểm tra trắc nghiệm ghi nhớ không đo đúng năng lực.","Tính tỷ lệ hoàn thành trên số người đã mở khóa học, làm số liệu đẹp hơn thực tế.","Dùng video, hình ảnh tải từ mạng không có giấy phép, vi phạm quyền tác giả."],en:["Labelling an objective as Understand while it requires a task, so a recall quiz fails to measure the skill.","Computing completion over learners who opened the course, inflating the result.","Using videos or images downloaded online without a license, infringing copyright."]},career:[{vi:"Chuyên viên phát triển học liệu số",en:"E-learning developer"},{vi:"Chuyên viên thiết kế chương trình học",en:"Instructional designer"},{vi:"Trưởng nhóm thiết kế học tập",en:"Senior learning experience designer / lead"},{vi:"Giám đốc học liệu số & công nghệ giáo dục",en:"Head of digital learning & EdTech"}],glossary:[{term:"Learning objective",vi:"Mục tiêu học tập mô tả hành vi đo được mà học viên làm được sau khi học.",en:"A statement of measurable behavior learners can perform after learning."},{term:"Storyboard",vi:"Kịch bản chi tiết từng màn hình gồm nội dung, hình ảnh, âm thanh và tương tác.",en:"Screen-by-screen script of content, visuals, audio and interactions."},{term:"SCORM",vi:"Chuẩn đóng gói học liệu số để LMS ghi nhận trạng thái hoàn thành và điểm số.",en:"A content packaging standard that lets an LMS track completion and scores."},{term:"xAPI",vi:"Chuẩn ghi nhận trải nghiệm học dạng câu lệnh, lưu vào kho LRS, kể cả ngoài LMS.",en:"A standard that records learning experiences as statements in an LRS, even outside the LMS."},{term:"Constructive alignment",vi:"Liên kết đồng bộ giữa mục tiêu, hoạt động học và hình thức đánh giá.",en:"Consistent alignment between objectives, learning activities and assessments."}],quiz:[{q:{vi:"Khóa học có 600 người được ghi danh, 450 người mở khóa học, 390 người hoàn thành và đạt. Tỷ lệ hoàn thành theo chuẩn là bao nhiêu?",en:"A course has 600 enrolled, 450 opened it and 390 completed and passed. What is the standard completion rate?"},options:{vi:["86,7%","75,0%","65,0%","55,0%"],en:["86.7%","75.0%","65.0%","55.0%"]},answer:2,explain:{vi:"Tỷ lệ hoàn thành = 390 / 600 x 100 = 65,0%; mẫu số là tổng số người được ghi danh.",en:"Completion = 390 / 600 x 100 = 65.0%; the denominator is total enrollment."}},{q:{vi:"Mục tiêu “Học viên so sánh hai phương án và chọn phương án tối ưu có lập luận” thuộc mức Bloom nào?",en:"The objective “Learners compare two options and justify the best one” is at which Bloom level?"},options:{vi:["Đánh giá","Nhớ","Hiểu","Vận dụng"],en:["Evaluate","Remember","Understand","Apply"]},answer:0,explain:{vi:"Đưa ra phán đoán có lập luận dựa trên tiêu chí là đặc trưng của mức Đánh giá.",en:"Making a justified judgment against criteria is the hallmark of the Evaluate level."}},{q:{vi:"Quan sát nhân viên áp dụng kỹ năng tại nơi làm việc sau 2 tháng là cấp độ nào trong mô hình Kirkpatrick?",en:"Observing staff applying skills at work 2 months later is which Kirkpatrick level?"},options:{vi:["Cấp 1 - Phản ứng","Cấp 2 - Học tập","Cấp 4 - Kết quả","Cấp 3 - Hành vi"],en:["Level 1 - Reaction","Level 2 - Learning","Level 4 - Results","Level 3 - Behavior"]},answer:3,explain:{vi:"Cấp 3 đo sự thay đổi hành vi, mức độ áp dụng kiến thức vào công việc thực tế.",en:"Level 3 measures behavior change and on-the-job application."}},{q:{vi:"Khách hàng yêu cầu dùng video tải từ khóa học trả phí của đơn vị khác. Bạn làm gì?",en:"The client asks you to use videos downloaded from another provider's paid course. What do you do?"},options:{vi:["Dùng vì chỉ học nội bộ","Từ chối, báo cáo và đề xuất tư liệu có giấy phép hoặc tự sản xuất","Cắt ngắn video để tránh bị phát hiện","Chờ khách tự quyết"],en:["Use them since it is internal","Refuse, escalate and propose licensed or in-house content","Trim the videos to avoid detection","Wait for the client to decide"]},answer:1,explain:{vi:"Dùng tác phẩm không được phép là xâm phạm quyền tác giả kể cả trong nội bộ; phải có phương án hợp pháp.",en:"Using works without permission infringes copyright even internally; a lawful alternative is required."}}],tools_en:["Interactive e-learning authoring tool","Learning management system (LMS)","Learning record store (LRS)","Screen recording and video editing software","Graphic design tool","Storyboard and objectives matrix templates"]}},"KK-867":{scenario:{company:"Học viện Anh ngữ Thiên Lý",supervisor:{name:"Ngô Thanh Bình",role:{vi:"Trưởng bộ môn IELTS",en:"Head of IELTS Department"}},ref_code:"IEL-3384",title:{vi:"Đúng tiêu chí. Đúng điểm tổng. Đúng sự thật.",en:"Right criterion. Right overall band. Right truth."},brief:{vi:"Bạn hoàn thiện phiếu kết quả thi thử IELTS IEL-3384 của một học viên lớp mục tiêu 6.5+. Điểm từng kỹ năng: Nghe 8.0, Đọc 6.5, Viết 6.0, Nói 6.5. Đề Viết Task 2 yêu cầu bàn cả nguyên nhân và giải pháp, nhưng bài chỉ phân tích nguyên nhân. Đối chiếu phiếu nhận xét nháp với khung tiêu chí và quy tắc làm tròn đã duyệt, sửa tiêu chí ghi nhận lỗi chính của bài Viết và điểm tổng (overall), rồi lập báo cáo có căn cứ.",en:"You are finalizing IELTS mock test report IEL-3384 for a learner in the 6.5+ target class. Skill scores: Listening 8.0, Reading 6.5, Writing 6.0, Speaking 6.5. The Writing Task 2 prompt asks for both causes and solutions, but the essay only discusses causes. Compare the draft feedback sheet with the approved criteria and rounding rules, correct the main criterion for the Writing issue and the overall band, then write an evidence-based report."},reference_title:{vi:"Khung tiêu chí chấm & quy tắc làm tròn đã duyệt · IEL-3384",en:"Approved marking criteria & rounding rules · IEL-3384"},fields:[{id:"W_CRITERION",label:{vi:"Tiêu chí ghi nhận lỗi chính bài Viết",en:"Main Writing criterion affected"},initial:"COHERENCE",expected:"TASK-RESPONSE",choices:["COHERENCE","TASK-RESPONSE","LEXICAL"],reference:"Khung tiêu chí Writing Task 2",hint:{vi:"Bài không trả lời đủ mọi phần của đề là vấn đề về mức độ đáp ứng yêu cầu đề bài, không phải tính liên kết.",en:"Failing to address every part of the prompt is about meeting task requirements, not cohesion."}},{id:"OVERALL",label:{vi:"Điểm tổng (overall band)",en:"Overall band score"},initial:"6.5",expected:"7.0",reference:"Bảng quy đổi điểm tổng",ref_value:{vi:"Nghe 8.0, Đọc 6.5, Viết 6.0, Nói 6.5; áp dụng quy tắc làm tròn của khung điểm",en:"Listening 8.0, Reading 6.5, Writing 6.0, Speaking 6.5; apply the band rounding rule"},hint:{vi:"Tính trung bình cộng 4 kỹ năng rồi xem phần lẻ: không được cắt bỏ phần lẻ.",en:"Average the four skills and check the decimal: never simply truncate it."}}],sop32:{vi:"Điểm tổng = trung bình cộng 4 kỹ năng, làm tròn đến nửa band gần nhất; phần lẻ .25 làm tròn lên .5, phần lẻ .75 làm tròn lên band nguyên kế tiếp.",en:"Overall band = mean of the four skills rounded to the nearest half band; a .25 decimal rounds up to .5 and a .75 decimal rounds up to the next whole band."},context:{label:"SỔ ĐIỂM THI THỬ / IEL-3384",metrics:[{label:{vi:"Nghe / Đọc",en:"Listening / Reading"},value:"8.0 / 6.5"},{label:{vi:"Viết / Nói",en:"Writing / Speaking"},value:"6.0 / 6.5"},{label:{vi:"Mục tiêu lớp",en:"Class target"},value:"6.5+"}]},crisis:{vi:"Quản lý tư vấn nhắn: “Ghi overall 7.5 cho học viên này để phụ huynh yên tâm đóng tiếp khóa sau. Mình đưa luôn tên và điểm lên bảng vàng quảng cáo, chưa cần hỏi ý kiến gia đình.”",en:"The admissions manager writes: “Put overall 7.5 for this learner so the parents keep paying for the next course. We will also post the name and score on our honor board ad without asking the family yet.”"},options:{safe:{vi:"Từ chối nâng điểm, báo đúng điểm làm tròn theo khung kèm kế hoạch cải thiện Task Response, báo Trưởng bộ môn; chỉ quảng cáo kết quả thật khi có sự đồng ý bằng văn bản của gia đình.",en:"Refuse to inflate the score, report the correctly rounded band with a Task Response improvement plan, inform the Head of Department; publish real results only with the family's written consent."},shortcut:{vi:"Ghi 7.5 vì chỉ là bài thi thử, không ảnh hưởng điểm thi thật.",en:"Write 7.5 because it is only a mock test and does not affect the real exam."},wait:{vi:"Chưa trả kết quả và chờ quản lý tư vấn tự trao đổi với phụ huynh.",en:"Hold the result and wait for the admissions manager to talk to the parents."}},questions:{vi:["Vì sao lỗi chính thuộc TASK-RESPONSE và điểm tổng là 7.0? Trình bày phép tính trung bình và quy tắc làm tròn.","Báo điểm thi thử cao hơn thực tế gây hại gì cho học viên và trung tâm? Bạn trao đổi với phụ huynh thế nào?"],en:["Why is the main issue TASK-RESPONSE and why is the overall band 7.0? Show the average and the rounding rule.","How does reporting an inflated mock score harm the learner and the school? How do you talk to the parents?"]},hints:{vi:["Đặt phiếu nhận xét nháp cạnh khung tiêu chí Writing và gạch chân yêu cầu nào của đề chưa được trả lời.","Áp dụng SOP mục 3.2: cộng 4 kỹ năng, chia 4 rồi áp quy tắc làm tròn cho phần lẻ.","Đọc lại SOP mục 4.2: kết quả đánh giá phải trung thực; dùng tên và điểm học viên cho quảng cáo cần sự đồng ý."],en:["Place the draft feedback next to the Writing criteria and underline which part of the prompt was not answered.","Apply SOP 3.2: add the four skills, divide by 4, then apply the rounding rule to the decimal.","Re-read SOP 4.2: results must be honest; using a learner's name and score in ads needs consent."]}},learning:{summary:{vi:"Giáo viên tiếng Anh quốc tế (TESOL/IELTS) thiết kế và giảng dạy các khóa tiếng Anh giao tiếp, học thuật và luyện thi, chẩn đoán trình độ, chấm chữa bài theo tiêu chí, phản hồi cá nhân hóa và theo dõi tiến bộ của học viên. Nghề đòi hỏi năng lực ngôn ngữ cao, phương pháp dạy hiện đại, hiểu sâu khung đánh giá và sự trung thực tuyệt đối khi báo cáo kết quả.",en:"A TESOL/IELTS instructor designs and teaches general, academic and test preparation English courses, diagnoses levels, marks against criteria, gives personalized feedback and tracks learner progress. The job requires high language proficiency, modern teaching methods, deep knowledge of assessment frameworks and absolute honesty in reporting results."},responsibilities:{vi:["Kiểm tra đầu vào, xếp lớp và xây dựng lộ trình học theo mục tiêu từng học viên.","Soạn giáo án theo đường hướng giao tiếp và nhiệm vụ, kết hợp 4 kỹ năng Nghe, Nói, Đọc, Viết.","Chấm chữa bài Viết và Nói theo tiêu chí công bố, phản hồi cụ thể, có ví dụ sửa.","Tổ chức thi thử định kỳ, tính điểm đúng quy tắc và báo cáo tiến bộ cho học viên, phụ huynh.","Tham gia sinh hoạt chuyên môn, dự giờ, chuẩn hóa chấm điểm giữa các giáo viên."],en:["Run placement tests, assign classes and build learning paths for each learner's goal.","Plan lessons using communicative and task-based approaches across Listening, Speaking, Reading and Writing.","Mark Writing and Speaking against published criteria with specific, example-based feedback.","Run regular mock tests, score them correctly and report progress to learners and parents.","Join professional development, peer observation and marker standardization sessions."]},competencies:[{name:{vi:"Năng lực ngôn ngữ",en:"Language proficiency"},desc:{vi:"Sử dụng tiếng Anh chuẩn xác ở trình độ cao, làm mẫu phát âm, ngữ pháp và từ vựng học thuật.",en:"Use highly accurate English and model pronunciation, grammar and academic vocabulary."}},{name:{vi:"Phương pháp giảng dạy",en:"Teaching methodology"},desc:{vi:"Áp dụng CLT, TBLT, dạy phân hóa và quản lý lớp học tích cực.",en:"Apply CLT, TBLT, differentiated instruction and active classroom management."}},{name:{vi:"Đánh giá theo tiêu chí",en:"Criterion-based assessment"},desc:{vi:"Chấm nhất quán theo mô tả band, xác định đúng tiêu chí bị ảnh hưởng và làm tròn điểm đúng quy tắc.",en:"Mark consistently to band descriptors, identify the affected criterion and round scores correctly."}},{name:{vi:"Phản hồi & huấn luyện",en:"Feedback & coaching"},desc:{vi:"Đưa phản hồi cụ thể, khả thi và theo dõi tiến bộ bằng dữ liệu bài làm.",en:"Give specific, actionable feedback and track progress with work samples."}},{name:{vi:"Liêm chính nghề nghiệp",en:"Professional integrity"},desc:{vi:"Báo cáo điểm trung thực, không dùng đề thi bị lộ và bảo vệ thông tin cá nhân học viên.",en:"Report scores honestly, never use leaked test papers and protect learners' personal data."}}],knowledge:{vi:["Khung tham chiếu chung châu Âu về ngôn ngữ (CEFR) với 6 bậc A1 đến C2.","Khung năng lực ngoại ngữ 6 bậc dùng cho Việt Nam ban hành kèm Thông tư 01/2014/TT-BGDĐT, tương thích CEFR.","Bốn tiêu chí chấm Writing IELTS: Task Achievement/Response, Coherence and Cohesion, Lexical Resource, Grammatical Range and Accuracy.","Quy tắc làm tròn điểm tổng IELTS đến nửa band gần nhất (.25 lên .5, .75 lên band nguyên kế tiếp).","Đường hướng giao tiếp (CLT), dạy học theo nhiệm vụ (TBLT) và đánh giá quá trình."],en:["The Common European Framework of Reference for Languages (CEFR) with six levels from A1 to C2.","Vietnam's six-level Foreign Language Proficiency Framework issued with Circular 01/2014/TT-BGDDT, aligned with CEFR.","The four IELTS Writing criteria: Task Achievement/Response, Coherence and Cohesion, Lexical Resource, Grammatical Range and Accuracy.","IELTS overall band rounding to the nearest half band (.25 up to .5, .75 up to the next whole band).","Communicative Language Teaching (CLT), Task-Based Language Teaching (TBLT) and formative assessment."]},tools:["Hệ thống quản lý học tập (LMS)","Bộ mô tả band điểm và rubric chấm","Phần mềm ghi âm chấm Nói","Kho đề luyện thi có bản quyền","Bảng tính sổ điểm và theo dõi tiến bộ","Bảng tương tác lớp học"],kpis:{vi:["Mức tăng band trung bình của học viên sau mỗi khóa.","Tỷ lệ học viên đạt mục tiêu đầu ra cam kết.","Độ lệch điểm chấm so với giám khảo chuẩn hóa (mục tiêu không quá 0.5 band).","Điểm hài lòng của học viên và tỷ lệ học tiếp khóa sau."],en:["Average band gain per course.","Share of learners reaching the committed target score.","Marking deviation from the standardized examiner (target no more than 0.5 band).","Learner satisfaction and re-enrollment rate."]},day:[{time:"08:00",vi:"Chuẩn bị giáo án, học liệu và nhiệm vụ nói theo chủ đề cho lớp sáng.",en:"Prepare the lesson plan, materials and speaking tasks for the morning class."},{time:"09:00",vi:"Dạy lớp Writing học thuật: phân tích đề, lập dàn ý và luyện viết đoạn thân bài.",en:"Teach academic Writing: analyze prompts, outline and practice body paragraphs."},{time:"13:30",vi:"Chấm chữa bài Task 2, ghi phản hồi theo 4 tiêu chí và ví dụ câu sửa.",en:"Mark Task 2 essays with feedback on the four criteria and corrected examples."},{time:"16:00",vi:"Phỏng vấn Speaking thử, ghi âm và chấm theo mô tả band.",en:"Run mock Speaking interviews, record them and score against band descriptors."},{time:"18:30",vi:"Dạy lớp tối và cập nhật sổ điểm, báo cáo tiến bộ cho phụ huynh.",en:"Teach the evening class and update the gradebook and progress reports for parents."}],mistakes:{vi:["Cắt bỏ phần lẻ khi tính điểm tổng thay vì làm tròn đúng quy tắc nửa band.","Ghi lỗi trả lời thiếu ý của đề vào tiêu chí liên kết, khiến học viên luyện sai trọng tâm.","Nâng điểm thi thử để giữ chân học viên hoặc làm quảng cáo, gây kỳ vọng sai và mất uy tín."],en:["Truncating the decimal of the overall band instead of applying the half-band rounding rule.","Logging an incomplete answer to the prompt under cohesion, so the learner practices the wrong focus.","Inflating mock scores to retain learners or for advertising, creating false expectations and losing trust."]},career:[{vi:"Trợ giảng tiếng Anh",en:"Teaching assistant"},{vi:"Giáo viên tiếng Anh TESOL/IELTS",en:"TESOL/IELTS instructor"},{vi:"Giáo viên cao cấp & điều phối chuyên môn",en:"Senior teacher & academic coordinator"},{vi:"Giám đốc học thuật trung tâm ngoại ngữ",en:"Director of studies"}],glossary:[{term:"Band descriptor",vi:"Bảng mô tả năng lực tương ứng từng mức band cho mỗi tiêu chí chấm.",en:"A table describing performance at each band level for every criterion."},{term:"Task Response",vi:"Tiêu chí đánh giá mức độ bài viết trả lời đầy đủ, phát triển ý và giữ lập trường rõ ràng.",en:"The criterion judging how fully an essay addresses the prompt, develops ideas and holds a clear position."},{term:"CEFR",vi:"Khung tham chiếu ngôn ngữ chung châu Âu, mô tả năng lực từ A1 đến C2.",en:"Common European Framework of Reference, describing proficiency from A1 to C2."},{term:"TBLT",vi:"Dạy học theo nhiệm vụ: học viên dùng ngôn ngữ để hoàn thành nhiệm vụ có ý nghĩa.",en:"Task-based teaching where learners use language to complete meaningful tasks."},{term:"Standardization",vi:"Chuẩn hóa chấm: các giáo viên chấm bài mẫu, so sánh và thống nhất cách áp dụng tiêu chí.",en:"Markers score sample scripts, compare and agree on how to apply criteria."}],quiz:[{q:{vi:"Học viên đạt Nghe 6.5, Đọc 6.5, Viết 5.5, Nói 6.5. Điểm tổng IELTS là bao nhiêu?",en:"A learner scores Listening 6.5, Reading 6.5, Writing 5.5, Speaking 6.5. What is the overall band?"},options:{vi:["6.0","6.25","5.5","6.5"],en:["6.0","6.25","5.5","6.5"]},answer:3,explain:{vi:"Trung bình = 25 / 4 = 6.25; phần lẻ .25 làm tròn lên 6.5.",en:"Mean = 25 / 4 = 6.25; a .25 decimal rounds up to 6.5."}},{q:{vi:"Theo Khung năng lực ngoại ngữ 6 bậc của Việt Nam, Bậc 4 tương đương trình độ CEFR nào?",en:"In Vietnam's six-level framework, Level 4 is equivalent to which CEFR level?"},options:{vi:["B1","B2","C1","A2"],en:["B1","B2","C1","A2"]},answer:1,explain:{vi:"Khung 6 bậc tương thích CEFR: Bậc 1-6 ứng với A1, A2, B1, B2, C1, C2, nên Bậc 4 là B2.",en:"The six levels align with CEFR A1 to C2, so Level 4 equals B2."}},{q:{vi:"Bài Task 2 chỉ trả lời một trong hai câu hỏi của đề. Tiêu chí nào bị ảnh hưởng trực tiếp nhất?",en:"A Task 2 essay answers only one of the two questions. Which criterion is most directly affected?"},options:{vi:["Task Response","Lexical Resource","Grammatical Range and Accuracy","Coherence and Cohesion"],en:["Task Response","Lexical Resource","Grammatical Range and Accuracy","Coherence and Cohesion"]},answer:0,explain:{vi:"Không đáp ứng đủ các phần của đề là hạn chế thuộc Task Response.",en:"Not addressing all parts of the prompt is a Task Response limitation."}},{q:{vi:"Quản lý yêu cầu nâng điểm thi thử để làm quảng cáo. Cách xử lý đúng là gì?",en:"A manager asks you to inflate a mock score for advertising. What is right?"},options:{vi:["Nâng điểm vì là thi thử","Nâng nửa band cho hợp lý","Từ chối, báo điểm thật, báo cáo và chỉ quảng cáo khi có kết quả thật và sự đồng ý","Không chấm bài nữa"],en:["Inflate it since it is a mock","Add half a band to look reasonable","Refuse, report the true score, escalate and advertise only real results with consent","Stop marking the test"]},answer:2,explain:{vi:"Điểm sai lệch gây hiểu nhầm cho học viên, phụ huynh và người tiêu dùng; quảng cáo phải dựa trên kết quả thật, có đồng ý.",en:"False scores mislead learners, parents and consumers; ads must use real, consented results."}}],tools_en:["Learning management system (LMS)","Band descriptors and scoring rubrics","Recording software for Speaking assessment","Licensed practice test bank","Gradebook and progress tracking spreadsheet","Interactive whiteboard"]}},"KK-868":{scenario:{company:"Cánh Diều Education Consulting",supervisor:{name:"Phan Đức Thịnh",role:{vi:"Giám đốc Tư vấn Du học",en:"Head of Study Abroad Counseling"}},ref_code:"SA-9056",title:{vi:"Đúng loại thị thực. Đúng tài chính. Đúng sự thật.",en:"Right visa. Right funds. Right truth."},brief:{vi:"Học sinh hồ sơ SA-9056 được một đại học Mỹ nhận vào chương trình cử nhân 4 năm toàn thời gian và cấp mẫu I-20. Chi phí năm đầu trên I-20: học phí 27.850 USD, sinh hoạt 14.600 USD, bảo hiểm và tài liệu 2.350 USD; học bổng của trường 8.500 USD (số liệu mô phỏng). Đối chiếu hồ sơ nháp với danh mục hồ sơ đã duyệt, sửa loại thị thực cần xin và số tiền gia đình phải chứng minh cho năm đầu (USD), rồi lập báo cáo có căn cứ.",en:"Student file SA-9056 has been admitted by a US university to a 4-year full-time bachelor's program and issued Form I-20. First-year costs on the I-20: tuition 27,850 USD, living 14,600 USD, insurance and books 2,350 USD; university scholarship 8,500 USD (training data). Compare the draft file with the approved checklist, correct the visa type to apply for and the first-year funds the family must document (USD), then write an evidence-based report."},reference_title:{vi:"Danh mục hồ sơ thị thực & bảng tài chính đã duyệt · SA-9056",en:"Approved visa checklist & funding sheet · SA-9056"},fields:[{id:"VISA_TYPE",label:{vi:"Loại thị thực cần xin",en:"Visa type to apply for"},initial:"J-1",expected:"F-1",choices:["J-1","F-1","M-1"],reference:"Danh mục hồ sơ thị thực",hint:{vi:"Xem trường cấp mẫu giấy tờ nào: I-20 cho chương trình học thuật hay DS-2019 cho chương trình trao đổi.",en:"Check which form the school issued: an I-20 for academic study or a DS-2019 for an exchange program."}},{id:"FUNDS_USD",label:{vi:"Số tiền cần chứng minh năm đầu (USD)",en:"First-year funds to document (USD)"},initial:"33950",expected:"36300",reference:"Bảng tài chính năm đầu",ref_value:{vi:"Học phí 27.850; sinh hoạt 14.600; bảo hiểm và tài liệu 2.350; học bổng 8.500 USD",en:"Tuition 27,850; living 14,600; insurance and books 2,350; scholarship 8,500 USD"},hint:{vi:"Cộng đủ mọi khoản chi phí ghi trên I-20 trước khi trừ học bổng đã được xác nhận.",en:"Add every cost line on the I-20 before deducting the confirmed scholarship."}}],sop32:{vi:"Số tiền cần chứng minh năm đầu = tổng chi phí ước tính trên I-20 (học phí + sinh hoạt + bảo hiểm, tài liệu) - học bổng hoặc tài trợ đã có văn bản xác nhận.",en:"First-year funds to document = total estimated costs on the I-20 (tuition + living + insurance and books) - scholarships or funding confirmed in writing."},context:{label:"CRM HỒ SƠ / SA-9056",metrics:[{label:{vi:"Mẫu giấy tờ trường cấp",en:"Form issued by school"},value:"I-20"},{label:{vi:"Tổng chi phí I-20",en:"Total I-20 costs"},value:"44,800 USD"},{label:{vi:"Học bổng mô phỏng",en:"Training scholarship"},value:"8,500 USD"}]},crisis:{vi:"Phụ huynh nói: “Bên dịch vụ làm giúp sổ tiết kiệm 40.000 USD trong một tuần, em cứ nộp kèm hồ sơ.” Trưởng nhóm kinh doanh nhắn thêm: “Kệ đi, nhiều nhà làm vậy, mất khách là mất hoa hồng.”",en:"The parent says: “A service can make us a 40,000 USD savings book in a week, just attach it to the file.” The sales lead adds: “Let it go, many families do it, losing the client means losing commission.”"},options:{safe:{vi:"Từ chối nộp giấy tờ tài chính không xác thực, giải thích rủi ro bị từ chối và cấm nhập cảnh, báo Giám đốc Tư vấn; hướng dẫn nguồn hợp lệ như tiền gửi thật, người bảo trợ, học bổng, khoản vay có hồ sơ.",en:"Refuse to submit non-genuine financial documents, explain the risk of refusal and entry bans, inform the Head of Counseling; guide the family to genuine savings, sponsors, scholarships or documented loans."},shortcut:{vi:"Nộp sổ tiết kiệm từ bên dịch vụ cho kịp lịch phỏng vấn, coi như trách nhiệm của gia đình.",en:"Submit the service's savings book to make the interview date, treating it as the family's responsibility."},wait:{vi:"Không góp ý và để gia đình tự quyết định giấy tờ tài chính nộp kèm.",en:"Say nothing and let the family decide which financial papers to attach."}},questions:{vi:["Vì sao học sinh cần thị thực F-1 và phải chứng minh 36300 USD cho năm đầu? Trình bày căn cứ từ I-20.","Hậu quả của việc nộp giấy tờ tài chính giả hoặc tạm thời là gì? Bạn tư vấn gia đình phương án hợp lệ nào?"],en:["Why does the student need an F-1 visa and 36300 USD of documented funds for year one? Cite the I-20.","What are the consequences of submitting fake or temporary financial documents? Which lawful options do you advise?"]},hints:{vi:["Đặt hồ sơ nháp cạnh danh mục hồ sơ thị thực và kiểm tra mẫu giấy tờ trường đã cấp.","Áp dụng SOP mục 3.2: cộng đủ chi phí trên I-20 rồi trừ học bổng có văn bản.","Đọc lại SOP mục 4.2: tư vấn viên không được tham gia hoặc làm ngơ trước hồ sơ gian dối; phải báo cáo và tư vấn phương án hợp lệ."],en:["Place the draft file next to the visa checklist and check which form the school issued.","Apply SOP 3.2: add all I-20 costs and then deduct the documented scholarship.","Re-read SOP 4.2: advisors must never take part in or ignore fraudulent files; escalate and advise lawful options."]}},learning:{summary:{vi:"Chuyên viên tư vấn tuyển sinh và du học quốc tế giúp học sinh, sinh viên chọn quốc gia, trường, ngành phù hợp năng lực và tài chính, xây dựng hồ sơ ứng tuyển, săn học bổng, chuẩn bị thị thực và định hướng trước khi lên đường. Công việc đòi hỏi hiểu biết hệ thống giáo dục nhiều nước, quy định thị thực cập nhật, kỹ năng tư vấn lấy học sinh làm trung tâm và chuẩn mực trung thực với hồ sơ.",en:"An academic and study abroad advisor helps students choose countries, institutions and majors that fit their ability and budget, builds applications, finds scholarships, prepares visas and runs pre-departure orientation. The role needs knowledge of many education systems, up-to-date visa rules, student-centered counseling skills and strict honesty with every file."},responsibilities:{vi:["Đánh giá học lực, ngoại ngữ, mục tiêu và ngân sách để lập danh sách trường phù hợp.","Hướng dẫn hồ sơ ứng tuyển: bảng điểm, bài luận, thư giới thiệu, chứng chỉ ngoại ngữ.","Tìm và hỗ trợ nộp học bổng, lập bảng chi phí và kế hoạch tài chính minh bạch.","Chuẩn bị hồ sơ thị thực đúng loại, luyện phỏng vấn và kiểm tra tính xác thực giấy tờ.","Định hướng trước khi đi, theo dõi học sinh sau nhập học và cập nhật quy định mới."],en:["Assess grades, language level, goals and budget to build a fitting school list.","Guide applications: transcripts, essays, recommendation letters and language certificates.","Find and support scholarship applications and build transparent cost and funding plans.","Prepare the right visa file, coach interviews and verify document authenticity.","Run pre-departure orientation, follow students after enrollment and track rule changes."]},competencies:[{name:{vi:"Hiểu biết hệ thống giáo dục quốc tế",en:"International education systems"},desc:{vi:"Nắm cấu trúc bậc học, yêu cầu đầu vào, kiểm định và cách quy đổi điểm ở các nước phổ biến.",en:"Know degree structures, entry requirements, accreditation and grade conversion in major destinations."}},{name:{vi:"Quy trình thị thực du học",en:"Student visa process"},desc:{vi:"Chọn đúng loại thị thực, giấy tờ xác nhận nhập học và chứng minh tài chính theo từng nước.",en:"Choose the right visa, admission documents and proof of funds for each country."}},{name:{vi:"Tư vấn lấy học sinh làm trung tâm",en:"Student-centered counseling"},desc:{vi:"Lắng nghe, khai thác mục tiêu thật và đưa lựa chọn khách quan, không chạy theo hoa hồng.",en:"Listen, uncover real goals and give objective options rather than chasing commission."}},{name:{vi:"Lập kế hoạch tài chính du học",en:"Study abroad financial planning"},desc:{vi:"Tính tổng chi phí, học bổng, tỷ giá và dòng tiền cho toàn khóa học.",en:"Compute total costs, scholarships, exchange rates and cash flow for the whole program."}},{name:{vi:"Liêm chính hồ sơ",en:"Application integrity"},desc:{vi:"Từ chối giấy tờ giả, bài luận viết hộ và cam kết sai sự thật; bảo vệ dữ liệu học sinh.",en:"Refuse fake documents, ghost-written essays and false statements; protect student data."}}],knowledge:{vi:["Thị thực du học Mỹ: F-1 cho chương trình học thuật và tiếng Anh (mẫu I-20), J-1 cho trao đổi (mẫu DS-2019), M-1 cho học nghề; phí SEVIS.","Thị thực Student của Anh dựa trên CAS; thị thực du học Úc subclass 500 cần CoE; Canada cấp giấy phép du học (study permit).","Nghị định 86/2021/NĐ-CP quy định việc công dân Việt Nam ra nước ngoài học tập, giảng dạy, nghiên cứu khoa học và trao đổi học thuật.","Quy định hiện hành về điều kiện kinh doanh dịch vụ tư vấn du học: đăng ký với cơ quan giáo dục, nhân sự có chứng chỉ nghiệp vụ.","Cách đọc chi phí trên giấy xác nhận nhập học, học bổng có điều kiện và quy đổi GPA giữa các thang điểm."],en:["US student visas: F-1 for academic and language study (Form I-20), J-1 for exchange (Form DS-2019), M-1 for vocational study; SEVIS fee.","The UK Student visa is based on a CAS; the Australian student visa subclass 500 needs a CoE; Canada issues a study permit.","Decree 86/2021/ND-CP on Vietnamese citizens going abroad for study, teaching, research and academic exchange.","Current rules on conditions for study abroad consulting services: registration with the education authority and certified advisors.","Reading costs on admission documents, conditional scholarships and GPA conversion between grading scales."]},tools:["Phần mềm CRM quản lý hồ sơ học sinh","Cổng nộp hồ sơ trực tuyến của các trường","Bảng tính chi phí và học bổng","Danh mục kiểm tra hồ sơ thị thực","Công cụ quy đổi điểm GPA","Lịch theo dõi hạn nộp hồ sơ"],kpis:{vi:["Tỷ lệ học sinh nhận thư mời nhập học từ trường trong danh sách phù hợp.","Tỷ lệ đậu thị thực ngay lần đầu.","Tổng giá trị học bổng đạt được trên mỗi học sinh.","Mức hài lòng của học sinh, phụ huynh sau 6 tháng nhập học."],en:["Share of students admitted to schools on their fit list.","First-time visa approval rate.","Total scholarship value won per student.","Student and parent satisfaction 6 months after enrollment."]},day:[{time:"08:30",vi:"Rà soát lịch hạn nộp hồ sơ, thư phản hồi của trường và cập nhật CRM.",en:"Review application deadlines and school replies and update the CRM."},{time:"10:00",vi:"Tư vấn trực tiếp gia đình mới: đánh giá năng lực, mục tiêu và ngân sách.",en:"Meet a new family to assess ability, goals and budget."},{time:"13:30",vi:"Góp ý bài luận, kiểm tra bảng điểm dịch thuật và thư giới thiệu.",en:"Give essay feedback and check translated transcripts and recommendation letters."},{time:"15:30",vi:"Lập bảng tài chính, kiểm tra giấy tờ chứng minh và luyện phỏng vấn thị thực.",en:"Build the funding sheet, check proof of funds and coach the visa interview."},{time:"17:30",vi:"Cập nhật thay đổi chính sách thị thực và chia sẻ với nhóm tư vấn.",en:"Track visa policy changes and brief the counseling team."}],mistakes:{vi:["Nhầm loại thị thực, ví dụ xin J-1 trong khi trường cấp I-20 cho chương trình cử nhân.","Bỏ sót khoản bảo hiểm, tài liệu hoặc trừ học bổng chưa được xác nhận khi tính số tiền cần chứng minh.","Làm ngơ hoặc hỗ trợ giấy tờ tài chính giả, khiến học sinh bị từ chối và có thể bị cấm nhập cảnh."],en:["Choosing the wrong visa, such as J-1 when the school issued an I-20 for a bachelor's program.","Missing insurance or books, or deducting unconfirmed scholarships, when computing required funds.","Ignoring or helping with fake financial documents, leading to refusal and possible entry bans."]},career:[{vi:"Nhân viên hỗ trợ hồ sơ du học",en:"Application support officer"},{vi:"Chuyên viên tư vấn du học",en:"Study abroad advisor"},{vi:"Trưởng nhóm tư vấn tuyển sinh quốc tế",en:"International admissions team lead"},{vi:"Giám đốc tư vấn du học & đối tác quốc tế",en:"Director of study abroad & international partnerships"}],glossary:[{term:"I-20",vi:"Giấy xác nhận đủ điều kiện nhập học do trường Mỹ cấp, căn cứ xin thị thực F-1 hoặc M-1.",en:"Certificate of eligibility issued by a US school, used to apply for an F-1 or M-1 visa."},{term:"SEVIS",vi:"Hệ thống quản lý thông tin sinh viên và khách trao đổi của Mỹ; người xin thị thực phải nộp phí SEVIS.",en:"The US student and exchange visitor information system; applicants must pay the SEVIS fee."},{term:"CAS",vi:"Mã xác nhận chấp nhận học do trường Anh cấp để xin thị thực Student.",en:"Confirmation of Acceptance for Studies issued by a UK institution for the Student visa."},{term:"Proof of funds",vi:"Bằng chứng tài chính hợp lệ cho thấy đủ khả năng chi trả học phí và sinh hoạt.",en:"Genuine evidence of the ability to pay tuition and living costs."},{term:"Conditional offer",vi:"Thư mời nhập học có điều kiện, ví dụ phải đạt điểm ngoại ngữ hoặc tốt nghiệp đúng hạn.",en:"An admission offer subject to conditions such as a language score or graduation on time."}],quiz:[{q:{vi:"Chi phí năm đầu trên I-20 là 52.000 USD, học bổng có xác nhận 12.000 USD. Gia đình cần chứng minh bao nhiêu?",en:"First-year I-20 costs are 52,000 USD with a confirmed 12,000 USD scholarship. How much must the family document?"},options:{vi:["52.000 USD","64.000 USD","12.000 USD","40.000 USD"],en:["52,000 USD","64,000 USD","12,000 USD","40,000 USD"]},answer:3,explain:{vi:"Số cần chứng minh = 52.000 - 12.000 = 40.000 USD.",en:"Funds to document = 52,000 - 12,000 = 40,000 USD."}},{q:{vi:"Trường Mỹ cấp DS-2019 cho chương trình trao đổi một học kỳ. Học sinh cần xin thị thực nào?",en:"A US school issues a DS-2019 for a one-semester exchange. Which visa does the student need?"},options:{vi:["F-1","J-1","M-1","B-2"],en:["F-1","J-1","M-1","B-2"]},answer:1,explain:{vi:"Mẫu DS-2019 dùng cho khách trao đổi diện J-1.",en:"Form DS-2019 is used for J-1 exchange visitors."}},{q:{vi:"Phụ huynh muốn dùng dịch vụ làm sổ tiết kiệm tạm thời để chứng minh tài chính. Bạn làm gì?",en:"Parents want a service to create a temporary savings book as proof of funds. What do you do?"},options:{vi:["Từ chối, giải thích rủi ro, báo cáo và hướng dẫn nguồn tài chính hợp lệ","Đồng ý vì là trách nhiệm của gia đình","Giới thiệu dịch vụ uy tín hơn","Im lặng để giữ khách"],en:["Refuse, explain the risks, escalate and guide genuine funding sources","Agree since it is the family's responsibility","Recommend a more reliable service","Stay silent to keep the client"]},answer:0,explain:{vi:"Giấy tờ tài chính không xác thực là gian dối hồ sơ thị thực; tư vấn viên phải từ chối và hướng dẫn phương án hợp pháp.",en:"Non-genuine financial documents are visa fraud; advisors must refuse and guide lawful options."}},{q:{vi:"Để xin thị thực Student của Anh, học sinh cần mã xác nhận nào từ trường?",en:"To apply for a UK Student visa, which reference does the student need from the institution?"},options:{vi:["I-20","CoE","CAS","DS-2019"],en:["I-20","CoE","CAS","DS-2019"]},answer:2,explain:{vi:"Trường Anh cấp CAS; CoE dùng cho Úc, I-20 và DS-2019 dùng cho Mỹ.",en:"UK institutions issue a CAS; a CoE is for Australia, while the I-20 and DS-2019 are for the US."}}],tools_en:["CRM for student application management","University online application portals","Cost and scholarship spreadsheets","Visa document checklist","GPA conversion tools","Application deadline tracking calendar"]}},"KK-869":{scenario:{company:"An Nhiên Wellbeing Partners",supervisor:{name:"Hồ Mỹ Linh",role:{vi:"Giám sát chuyên môn tham vấn",en:"Clinical Supervisor"}},ref_code:"EAP-1472",title:{vi:"Đúng điểm sàng lọc. Đúng mức ưu tiên. Đúng bảo mật.",en:"Right screening score. Right priority. Right confidentiality."},brief:{vi:"Đây là tình huống đào tạo. Nhân viên mã EAP-1472 (dữ liệu hư cấu) của một doanh nghiệp khách hàng làm thang PHQ-9 trước buổi tham vấn đầu. Điểm câu 1 đến câu 9 lần lượt: 1, 2, 2, 1, 3, 2, 2, 2, 1; câu 9 (ý nghĩ tự làm hại bản thân) được chọn mức “vài ngày”. Đối chiếu phiếu sàng lọc nháp với quy trình phân loại rủi ro đã duyệt, sửa mức ưu tiên xử lý và tổng điểm PHQ-9, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. Employee EAP-1472 (fictional data) of a client company completed the PHQ-9 before the first counseling session. Item 1 to item 9 scores: 1, 2, 2, 1, 3, 2, 2, 2, 1; item 9 (thoughts of self-harm) was marked “several days”. Compare the draft screening sheet with the approved risk triage procedure, correct the handling priority and the PHQ-9 total score, then write an evidence-based report."},reference_title:{vi:"Quy trình sàng lọc & phân loại rủi ro đã duyệt · EAP-1472",en:"Approved screening & risk triage procedure · EAP-1472"},fields:[{id:"TRIAGE",label:{vi:"Mức ưu tiên xử lý",en:"Handling priority"},initial:"ROUTINE",expected:"SAFETY-SAMEDAY",choices:["ROUTINE","PRIORITY-48H","SAFETY-SAMEDAY"],reference:"Bảng phân loại rủi ro",hint:{vi:"Câu 9 có điểm khác 0 là tín hiệu nguy cơ, kích hoạt đánh giá an toàn bất kể tổng điểm.",en:"Any non-zero item 9 is a risk signal that triggers a safety assessment regardless of the total."}},{id:"PHQ9_TOTAL",label:{vi:"Tổng điểm PHQ-9",en:"PHQ-9 total score"},initial:"15",expected:"16",reference:"Phiếu chấm thang PHQ-9",ref_value:{vi:"Điểm câu 1-9: 1, 2, 2, 1, 3, 2, 2, 2, 1",en:"Item 1-9 scores: 1, 2, 2, 1, 3, 2, 2, 2, 1"},hint:{vi:"Đếm lại đủ 9 câu; bản nháp có thể đã bỏ sót một câu khi cộng.",en:"Recount all 9 items; the draft may have skipped one item when adding."}}],sop32:{vi:"Tổng điểm PHQ-9 = cộng điểm cả 9 câu (mỗi câu 0-3, tối đa 27), không bỏ câu nào. Mức độ: 5-9 nhẹ, 10-14 trung bình, 15-19 trung bình nặng, 20-27 nặng.",en:"PHQ-9 total = sum of all 9 items (each 0-3, maximum 27), skipping none. Severity: 5-9 mild, 10-14 moderate, 15-19 moderately severe, 20-27 severe."},context:{label:"HỒ SƠ THAM VẤN / EAP-1472",metrics:[{label:{vi:"Thang sàng lọc",en:"Screening tool"},value:"PHQ-9"},{label:{vi:"Điểm câu 9",en:"Item 9 score"},value:"1"},{label:{vi:"Buổi tham vấn",en:"Session"},value:"1/6"}]},crisis:{vi:"Trưởng phòng nhân sự của doanh nghiệp khách hàng gọi: “Gửi tôi kết quả PHQ-9 và ghi chép buổi tham vấn của nhân viên này. Công ty đang cân nhắc cho bạn ấy nghỉ việc, chuyện nội bộ nên không cần hỏi ý kiến nhân viên.”",en:"The client company's HR manager calls: “Send me this employee's PHQ-9 result and session notes. We are considering letting them go, it is internal so there is no need to ask the employee.”"},options:{safe:{vi:"Từ chối cung cấp thông tin định danh khi chưa có đồng ý bằng văn bản, chỉ gửi báo cáo tổng hợp theo hợp đồng EAP, báo Giám sát chuyên môn và tiếp tục quy trình an toàn với thân chủ.",en:"Decline to share identifiable information without written consent, send only aggregate reports under the EAP contract, inform the Clinical Supervisor and continue the safety procedure with the client."},shortcut:{vi:"Gửi kết quả và ghi chép cho nhân sự vì doanh nghiệp là bên trả phí dịch vụ.",en:"Send the result and notes to HR because the company pays for the service."},wait:{vi:"Không trả lời nhân sự và tạm dừng làm việc với thân chủ cho đến khi hai bên tự thống nhất.",en:"Ignore HR and pause work with the client until both sides sort it out."}},questions:{vi:["Vì sao mức ưu tiên phải là SAFETY-SAMEDAY và tổng điểm đúng là 16? Trình bày căn cứ từ phiếu PHQ-9.","Giới hạn bảo mật trong tham vấn là gì? Bạn phản hồi yêu cầu của nhân sự doanh nghiệp như thế nào?"],en:["Why must the priority be SAFETY-SAMEDAY and why is the correct total 16? Cite the PHQ-9 sheet.","What are the limits of confidentiality in counseling? How do you respond to the company's HR request?"]},hints:{vi:["Đặt phiếu sàng lọc nháp cạnh bảng phân loại rủi ro và kiểm tra riêng điểm câu 9.","Áp dụng SOP mục 3.2: cộng đủ 9 câu rồi đối chiếu ngưỡng mức độ.","Đọc lại SOP mục 4.2: thông tin tham vấn chỉ chia sẻ khi thân chủ đồng ý hoặc trong giới hạn bảo mật đã thông báo."],en:["Place the draft sheet next to the triage table and check item 9 on its own.","Apply SOP 3.2: add all 9 items and then compare with the severity bands.","Re-read SOP 4.2: counseling information is shared only with client consent or within the stated limits of confidentiality."]}},learning:{summary:{vi:"Chuyên viên tham vấn tâm lý học đường và công sở hỗ trợ học sinh, sinh viên và người lao động đối mặt với căng thẳng, khó khăn cảm xúc, quan hệ và học tập, công việc. Công việc gồm sàng lọc bằng thang đo chuẩn hóa, tham vấn cá nhân và nhóm, can thiệp khủng hoảng, chuyển tuyến khi vượt phạm vi và tư vấn phòng ngừa cho tổ chức, trên nền tảng bảo mật và đạo đức nghề.",en:"A school and workplace counseling specialist supports students and employees facing stress, emotional, relationship, study or work difficulties. The work covers screening with standardized scales, individual and group counseling, crisis intervention, referral when beyond scope and preventive advice to organizations, all grounded in confidentiality and professional ethics."},responsibilities:{vi:["Tiếp nhận, sàng lọc ban đầu bằng thang đo chuẩn hóa và phân loại mức ưu tiên.","Tham vấn cá nhân, nhóm theo mục tiêu thống nhất với thân chủ và kế hoạch rõ ràng.","Đánh giá nguy cơ, lập kế hoạch an toàn và phối hợp hỗ trợ khẩn cấp khi cần.","Chuyển tuyến tới bác sĩ chuyên khoa tâm thần hoặc nhà tâm lý lâm sàng khi vượt phạm vi.","Tổ chức chương trình phòng ngừa, báo cáo tổng hợp không định danh cho nhà trường, doanh nghiệp."],en:["Receive clients, screen them with standardized scales and assign priority.","Run individual and group counseling with goals agreed with the client and a clear plan.","Assess risk, build safety plans and coordinate emergency support when needed.","Refer to psychiatrists or clinical psychologists when issues exceed scope.","Run prevention programs and give anonymized aggregate reports to schools and employers."]},competencies:[{name:{vi:"Lắng nghe & thiết lập liên minh trị liệu",en:"Listening & therapeutic alliance"},desc:{vi:"Lắng nghe tích cực, thấu cảm, không phán xét để thân chủ an tâm chia sẻ.",en:"Listen actively, empathize and stay non-judgmental so clients feel safe to share."}},{name:{vi:"Sàng lọc & đánh giá nguy cơ",en:"Screening & risk assessment"},desc:{vi:"Chấm thang đo chính xác, đọc tín hiệu nguy cơ và phân loại mức ưu tiên đúng quy trình.",en:"Score scales accurately, read risk signals and triage according to procedure."}},{name:{vi:"Kỹ thuật can thiệp",en:"Intervention techniques"},desc:{vi:"Vận dụng tham vấn tập trung giải pháp, nhận thức hành vi cơ bản và phỏng vấn tạo động lực.",en:"Apply solution-focused counseling, basic cognitive behavioral techniques and motivational interviewing."}},{name:{vi:"Bảo mật & đạo đức nghề",en:"Confidentiality & ethics"},desc:{vi:"Có đồng thuận có hiểu biết, nêu rõ giới hạn bảo mật và từ chối chia sẻ thông tin trái nguyên tắc.",en:"Obtain informed consent, state the limits of confidentiality and refuse improper disclosure."}},{name:{vi:"Phối hợp & chuyển tuyến",en:"Coordination & referral"},desc:{vi:"Nhận biết giới hạn năng lực, kết nối dịch vụ y tế chuyên khoa và theo dõi sau chuyển tuyến.",en:"Recognize scope limits, connect clients to specialist health services and follow up after referral."}}],knowledge:{vi:["Nguyên tắc đạo đức tham vấn: tôn trọng, không gây hại, bảo mật, đồng thuận có hiểu biết và giới hạn bảo mật khi có nguy cơ gây hại nghiêm trọng.","Thông tư 31/2017/TT-BGDĐT hướng dẫn thực hiện công tác tư vấn tâm lý cho học sinh trong trường phổ thông.","Thang PHQ-9 (0-27) và GAD-7 (0-21, ngưỡng 5, 10, 15) là công cụ sàng lọc, không thay thế chẩn đoán lâm sàng.","Phân biệt tham vấn với chẩn đoán, điều trị rối loạn tâm thần thuộc phạm vi bác sĩ chuyên khoa và nhà tâm lý lâm sàng được cấp phép.","Quy định hiện hành về bảo vệ dữ liệu cá nhân: thông tin sức khỏe tâm thần là dữ liệu nhạy cảm, cần đồng ý và bảo vệ tăng cường."],en:["Counseling ethics: respect, non-maleficence, confidentiality, informed consent and limits of confidentiality when there is a risk of serious harm.","Circular 31/2017/TT-BGDDT guiding psychological counseling for students in general schools.","PHQ-9 (0-27) and GAD-7 (0-21, cut-offs 5, 10, 15) are screening tools and do not replace clinical diagnosis.","Distinguish counseling from diagnosing and treating mental disorders, which belong to licensed psychiatrists and clinical psychologists.","Current personal data protection rules: mental health information is sensitive data requiring consent and enhanced protection."]},tools:["Thang sàng lọc PHQ-9 và GAD-7","Hồ sơ tham vấn điện tử có mã hóa","Mẫu kế hoạch an toàn","Nền tảng tham vấn trực tuyến bảo mật","Phiếu đồng thuận có hiểu biết","Danh bạ chuyển tuyến chuyên khoa"],kpis:{vi:["Tỷ lệ ca có tín hiệu nguy cơ được đánh giá an toàn trong ngày (mục tiêu 100%).","Mức cải thiện điểm thang đo giữa buổi đầu và buổi cuối.","Tỷ lệ thân chủ hoàn thành kế hoạch tham vấn đã thống nhất.","Số sự cố lộ thông tin thân chủ (mục tiêu bằng 0)."],en:["Share of risk-flagged cases given a same-day safety assessment (target 100%).","Scale score improvement from first to last session.","Share of clients completing the agreed counseling plan.","Client confidentiality breaches (target zero)."]},day:[{time:"08:00",vi:"Rà danh sách ca mới, kiểm tra thang sàng lọc và đánh dấu ca có tín hiệu nguy cơ.",en:"Review new referrals, check screening scales and flag cases with risk signals."},{time:"09:30",vi:"Tham vấn cá nhân theo lịch, ghi chép ca ngắn gọn, khách quan sau mỗi buổi.",en:"Hold scheduled individual sessions and write brief, objective notes after each."},{time:"13:30",vi:"Đánh giá an toàn ca ưu tiên, cùng thân chủ lập kế hoạch an toàn và kết nối hỗ trợ.",en:"Run a safety assessment for a priority case, build a safety plan with the client and connect support."},{time:"15:30",vi:"Họp giám sát chuyên môn, thảo luận ca khó và quyết định chuyển tuyến.",en:"Attend clinical supervision, discuss complex cases and decide on referrals."},{time:"17:00",vi:"Tổng hợp số liệu không định danh và chuẩn bị buổi chia sẻ phòng ngừa căng thẳng.",en:"Compile anonymized data and prepare a stress prevention workshop."}],mistakes:{vi:["Chỉ nhìn tổng điểm mà bỏ qua câu 9 của PHQ-9, làm chậm đánh giá an toàn.","Cộng thiếu câu khi chấm thang đo, dẫn tới phân loại mức độ sai.","Chia sẻ ghi chép tham vấn cho nhà trường, doanh nghiệp khi chưa có đồng ý của thân chủ."],en:["Looking only at the total and missing PHQ-9 item 9, delaying the safety assessment.","Leaving out an item when scoring a scale, leading to the wrong severity band.","Sharing session notes with a school or employer without the client's consent."]},career:[{vi:"Cán bộ hỗ trợ tâm lý",en:"Psychological support assistant"},{vi:"Chuyên viên tham vấn tâm lý",en:"Counseling specialist"},{vi:"Chuyên viên tham vấn cao cấp & giám sát chuyên môn",en:"Senior counselor & clinical supervisor"},{vi:"Giám đốc chương trình sức khỏe tinh thần",en:"Director of mental wellbeing programs"}],glossary:[{term:"PHQ-9",vi:"Bảng hỏi sức khỏe bệnh nhân 9 câu dùng sàng lọc và theo dõi mức độ triệu chứng trầm cảm.",en:"A 9-item patient health questionnaire for screening and tracking depressive symptom severity."},{term:"Informed consent",vi:"Đồng thuận có hiểu biết: thân chủ được giải thích mục đích, quy trình, giới hạn bảo mật trước khi đồng ý.",en:"The client agrees after learning the purpose, process and limits of confidentiality."},{term:"Safety plan",vi:"Kế hoạch an toàn do thân chủ và nhà tham vấn cùng xây dựng: dấu hiệu cảnh báo, cách ứng phó và người liên hệ.",en:"A plan built with the client listing warning signs, coping steps and people to contact."},{term:"EAP",vi:"Chương trình hỗ trợ nhân viên do doanh nghiệp tài trợ, cung cấp tham vấn bảo mật cho người lao động.",en:"Employee assistance program funded by employers, offering confidential counseling to staff."},{term:"Referral",vi:"Chuyển tuyến: kết nối thân chủ với dịch vụ chuyên khoa phù hợp khi vượt phạm vi tham vấn.",en:"Connecting the client to a suitable specialist service when needs exceed counseling scope."}],quiz:[{q:{vi:"Điểm PHQ-9 các câu: 1, 2, 1, 2, 2, 1, 1, 0, 0. Tổng điểm thuộc mức nào?",en:"PHQ-9 item scores: 1, 2, 1, 2, 2, 1, 1, 0, 0. Which severity band applies?"},options:{vi:["Nhẹ (5-9)","Trung bình nặng (15-19)","Trung bình (10-14)","Tối thiểu (0-4)"],en:["Mild (5-9)","Moderately severe (15-19)","Moderate (10-14)","Minimal (0-4)"]},answer:2,explain:{vi:"Tổng = 10, thuộc mức trung bình (10-14); câu 9 bằng 0 nên không có tín hiệu nguy cơ từ câu này.",en:"Total = 10, which is moderate (10-14); item 9 is 0, so there is no risk signal from that item."}},{q:{vi:"Doanh nghiệp trả phí EAP yêu cầu xem ghi chép tham vấn của một nhân viên. Bạn làm gì?",en:"The employer paying for the EAP asks to see an employee's session notes. What do you do?"},options:{vi:["Từ chối khi chưa có đồng ý bằng văn bản, chỉ gửi báo cáo tổng hợp không định danh","Gửi ngay vì doanh nghiệp trả phí","Gửi bản tóm tắt bằng lời qua điện thoại","Hỏi đồng nghiệp rồi gửi"],en:["Decline without written consent and send only anonymized aggregate reports","Send them since the employer pays","Summarize them verbally by phone","Ask a colleague, then send"]},answer:0,explain:{vi:"Bảo mật thuộc về thân chủ; bên tài trợ chỉ nhận số liệu tổng hợp theo hợp đồng, trừ khi thân chủ đồng ý.",en:"Confidentiality belongs to the client; sponsors receive only contracted aggregate data unless the client consents."}},{q:{vi:"Tổng PHQ-9 chỉ 7 điểm nhưng câu 9 được chọn mức “vài ngày”. Bước tiếp theo đúng là gì?",en:"The PHQ-9 total is only 7 but item 9 is marked “several days”. What is the right next step?"},options:{vi:["Xếp lịch thường vì tổng điểm thấp","Gửi bài đọc tự giúp và hẹn tháng sau","Bỏ qua vì có thể khách chọn nhầm","Đánh giá an toàn ngay trong ngày, lập kế hoạch an toàn và báo giám sát chuyên môn"],en:["Schedule routinely since the total is low","Send self-help reading and meet next month","Ignore it as a possible mistake","Do a same-day safety assessment, build a safety plan and inform the supervisor"]},answer:3,explain:{vi:"Câu 9 khác 0 là tín hiệu nguy cơ độc lập với tổng điểm, phải đánh giá an toàn kịp thời theo quy trình.",en:"A non-zero item 9 is a risk signal independent of the total and requires a timely safety assessment."}},{q:{vi:"Thân chủ có triệu chứng cần chẩn đoán và cân nhắc dùng thuốc. Nhà tham vấn nên làm gì?",en:"A client shows symptoms needing diagnosis and possible medication. What should the counselor do?"},options:{vi:["Tự chẩn đoán và khuyên dùng thuốc","Chuyển tuyến tới bác sĩ chuyên khoa tâm thần và tiếp tục hỗ trợ phối hợp","Kết thúc tham vấn ngay","Khuyên thân chủ tự mua thuốc"],en:["Diagnose and advise medication yourself","Refer to a psychiatrist and keep providing coordinated support","End counseling immediately","Tell the client to buy medicine"]},answer:1,explain:{vi:"Chẩn đoán và kê đơn vượt phạm vi tham vấn; chuyển tuyến đúng giúp thân chủ được điều trị an toàn.",en:"Diagnosis and prescribing exceed counseling scope; proper referral keeps the client safe."}}],tools_en:["PHQ-9 and GAD-7 screening scales","Encrypted electronic counseling records","Safety plan template","Secure online counseling platform","Informed consent form","Specialist referral directory"]}},"KK-870":{scenario:{company:"Ngân Hà Language Solutions",supervisor:{name:"Trịnh Quốc Việt",role:{vi:"Trưởng phòng Chất lượng Biên dịch",en:"Translation Quality Manager"}},ref_code:"TR-5521",title:{vi:"Đúng quy trình. Đúng báo giá. Đúng bảo mật.",en:"Right workflow. Right quote. Right confidentiality."},brief:{vi:"Bạn kiểm tra hồ sơ dự án TR-5521: dịch sổ tay vận hành máy nén khí công nghiệp từ tiếng Anh sang tiếng Việt, 12.400 từ nguồn. Phân tích bộ nhớ dịch: 6.800 từ mới, 3.200 từ khớp mờ 75-99%, 2.400 từ khớp 100%. Đơn giá hợp đồng 1.200 VND/từ (số liệu mô phỏng). Đối chiếu phiếu dự án nháp với hợp đồng và quy trình chất lượng đã duyệt, sửa bước kiểm soát bắt buộc sau khi dịch và giá trị báo giá (VND), rồi lập báo cáo có căn cứ.",en:"You are checking project file TR-5521: translating an industrial air compressor operating manual from English into Vietnamese, 12,400 source words. Translation memory analysis: 6,800 new words, 3,200 fuzzy matches at 75-99%, 2,400 exact 100% matches. Contract rate 1,200 VND per word (training data). Compare the draft project sheet with the contract and the approved quality workflow, correct the mandatory post-translation control step and the quote value (VND), then write an evidence-based report."},reference_title:{vi:"Hợp đồng dịch vụ & quy trình chất lượng đã duyệt · TR-5521",en:"Approved service contract & quality workflow · TR-5521"},fields:[{id:"QA_STEP",label:{vi:"Bước kiểm soát bắt buộc sau khi dịch",en:"Mandatory post-translation control"},initial:"SELF-CHECK",expected:"REVISION",choices:["SELF-CHECK","REVIEW","REVISION"],reference:"Quy trình chất lượng biên dịch",hint:{vi:"Phân biệt: tự kiểm tra của người dịch, hiệu đính song ngữ bởi người thứ hai và rà soát đơn ngữ bản đích.",en:"Distinguish the translator's own check, bilingual revision by a second linguist and monolingual review of the target."}},{id:"QUOTE_VND",label:{vi:"Giá trị báo giá (VND)",en:"Quote value (VND)"},initial:"14880000",expected:"11328000",reference:"Phụ lục đơn giá hợp đồng",ref_value:{vi:"Phân tích bộ nhớ dịch: 6.800 từ mới, 3.200 khớp mờ, 2.400 khớp 100%; đơn giá 1.200 VND/từ",en:"TM analysis: 6,800 new, 3,200 fuzzy, 2,400 exact matches; rate 1,200 VND per word"},hint:{vi:"Hợp đồng không tính mọi từ theo giá đầy đủ: mỗi mức khớp bộ nhớ dịch có hệ số riêng.",en:"The contract does not bill every word at full rate: each TM match band has its own weight."}}],sop32:{vi:"Số từ quy đổi = từ mới x 100% + khớp mờ 75-99% x 60% + khớp 100% x 30%; giá trị báo giá = số từ quy đổi x đơn giá hợp đồng (số liệu mô phỏng).",en:"Weighted words = new words x 100% + fuzzy 75-99% x 60% + exact 100% x 30%; quote value = weighted words x contract rate (training data)."},context:{label:"CAT / TR-5521",metrics:[{label:{vi:"Tổng từ nguồn",en:"Total source words"},value:"12,400"},{label:{vi:"Mới / khớp mờ / khớp 100%",en:"New / fuzzy / exact"},value:"6,800 / 3,200 / 2,400"},{label:{vi:"Đơn giá mô phỏng",en:"Training rate"},value:"1,200 VND/word"}]},crisis:{vi:"Quản lý dự án nhắn: “Dán cả sổ tay vào trang dịch máy miễn phí trên mạng cho nhanh, bỏ bước hiệu đính, giao khách là bản dịch do người làm. Khách cần trước 8 giờ sáng mai.” Tài liệu có điều khoản bảo mật.",en:"The project manager writes: “Paste the whole manual into a free online machine translation site, skip revision and deliver it as human translation. The client needs it before 8 a.m. tomorrow.” The document is under a confidentiality clause."},options:{safe:{vi:"Từ chối đưa tài liệu lên công cụ công cộng và giao bản không hiệu đính, báo Trưởng phòng Chất lượng; đề xuất chia việc, dùng công cụ dịch máy được khách chấp thuận có hiệu đính sau dịch máy hoặc xin lùi hạn.",en:"Refuse to upload the document to a public tool or deliver unrevised work, inform the Quality Manager; propose splitting the work, a client-approved MT engine with post-editing or a deadline extension."},shortcut:{vi:"Dùng dịch máy miễn phí, sửa sơ qua và giao khách là bản dịch người làm cho kịp hạn.",en:"Use free machine translation, skim-edit it and deliver it as human work to meet the deadline."},wait:{vi:"Không làm gì và chờ quản lý dự án tự tìm người dịch khác.",en:"Do nothing and wait for the project manager to find another translator."}},questions:{vi:["Vì sao bước bắt buộc là REVISION và báo giá đúng là 11328000 VND? Trình bày căn cứ từ quy trình và hợp đồng.","Đưa tài liệu mật lên công cụ dịch công cộng và giao bản dịch máy như bản người dịch gây những rủi ro gì? Bạn xử lý hạn gấp thế nào?"],en:["Why is REVISION the mandatory step and why is the correct quote 11328000 VND? Cite the workflow and contract.","What risks come from uploading confidential files to public MT and passing machine output off as human translation? How do you handle the tight deadline?"]},hints:{vi:["Đặt phiếu dự án nháp cạnh quy trình chất lượng và xác định bước nào do người thứ hai thực hiện.","Áp dụng SOP mục 3.2: nhân từng nhóm từ với hệ số tương ứng trước khi nhân đơn giá.","Đọc lại SOP mục 4.2: tài liệu có điều khoản bảo mật chỉ được xử lý trên công cụ đã được phê duyệt."],en:["Place the draft project sheet next to the quality workflow and identify the step done by a second person.","Apply SOP 3.2: weight each word band before multiplying by the rate.","Re-read SOP 4.2: confidential documents may be processed only in approved tools."]}},learning:{summary:{vi:"Biên - phiên dịch viên thương mại và kỹ thuật chuyển ngữ chính xác hợp đồng, tài liệu kỹ thuật, hồ sơ thầu, tài liệu marketing và phiên dịch trong đàm phán, hội thảo, đào tạo. Công việc đòi hỏi năng lực song ngữ cao, kiến thức chuyên ngành, quản lý thuật ngữ, thành thạo công cụ CAT, tuân thủ quy trình chất lượng và cam kết bảo mật thông tin khách hàng.",en:"A commercial and technical translator and interpreter accurately renders contracts, technical documents, tenders and marketing materials and interprets in negotiations, conferences and training. The work demands high bilingual competence, domain knowledge, terminology management, mastery of CAT tools, quality workflow compliance and strict client confidentiality."},responsibilities:{vi:["Phân tích tài liệu nguồn, xây dựng bảng thuật ngữ và câu hỏi làm rõ với khách hàng.","Biên dịch trên công cụ CAT, tận dụng bộ nhớ dịch và bảo đảm nhất quán thuật ngữ.","Hiệu đính chéo, kiểm tra QA tự động về số liệu, đơn vị, thẻ định dạng và thuật ngữ.","Phiên dịch nối tiếp hoặc song song trong họp, đàm phán, đào tạo kỹ thuật.","Lập báo giá theo phân tích bộ nhớ dịch, quản lý hạn giao và lưu trữ an toàn tài liệu."],en:["Analyze source documents, build glossaries and raise queries with the client.","Translate in CAT tools, leverage translation memory and keep terminology consistent.","Cross-revise and run automated QA on numbers, units, tags and terminology.","Interpret consecutively or simultaneously in meetings, negotiations and technical training.","Quote from TM analysis, manage deadlines and store documents securely."]},competencies:[{name:{vi:"Năng lực song ngữ chuyên ngành",en:"Specialized bilingual competence"},desc:{vi:"Hiểu sâu cấu trúc, văn phong pháp lý, kỹ thuật ở cả hai ngôn ngữ và chọn từ chính xác.",en:"Master legal and technical structures and styles in both languages and choose precise terms."}},{name:{vi:"Quản lý thuật ngữ",en:"Terminology management"},desc:{vi:"Xây dựng, cập nhật termbase và bảo đảm thuật ngữ nhất quán trong toàn dự án.",en:"Build and update termbases and keep terminology consistent across the project."}},{name:{vi:"Công nghệ dịch thuật",en:"Translation technology"},desc:{vi:"Thành thạo CAT, bộ nhớ dịch, QA tự động và hiệu đính sau dịch máy có kiểm soát.",en:"Master CAT tools, translation memory, automated QA and controlled MT post-editing."}},{name:{vi:"Kỹ năng phiên dịch",en:"Interpreting skills"},desc:{vi:"Ghi nhớ ngắn hạn, ghi chép nhanh, xử lý áp lực và giữ trung lập khi phiên dịch.",en:"Use short-term memory, fast note-taking, composure and neutrality when interpreting."}},{name:{vi:"Bảo mật & liêm chính",en:"Confidentiality & integrity"},desc:{vi:"Giữ bí mật tài liệu, minh bạch về dịch máy và từ chối làm sai lệch nội dung.",en:"Keep documents confidential, be transparent about MT use and refuse to distort content."}}],knowledge:{vi:["ISO 17100:2015 về dịch vụ biên dịch: hiệu đính (revision) bởi người thứ hai là bước bắt buộc.","ISO 18587:2017 về hiệu đính bản dịch máy (post-editing) và yêu cầu năng lực người hiệu đính.","ISO 18841:2018 về yêu cầu chung đối với dịch vụ phiên dịch.","Nghị định 23/2015/NĐ-CP về chứng thực, trong đó có chứng thực chữ ký người dịch.","Các hình thức phiên dịch: nối tiếp, song song (cabin), thì thầm, dịch nhìn văn bản."],en:["ISO 17100:2015 on translation services: revision by a second person is a mandatory step.","ISO 18587:2017 on post-editing of machine translation output and post-editor competence.","ISO 18841:2018 on general requirements for interpreting services.","Decree 23/2015/ND-CP on certification, including certification of the translator's signature.","Interpreting modes: consecutive, simultaneous (booth), whispered and sight translation."]},tools:["Phần mềm CAT có bộ nhớ dịch và termbase","Công cụ QA thuật ngữ và số liệu","Công cụ dịch máy được khách chấp thuận","Thiết bị phiên dịch cabin","Phần mềm so sánh và căn chỉnh văn bản","Kho lưu trữ tài liệu mã hóa"],kpis:{vi:["Số lỗi nghiêm trọng trên 1.000 từ theo thang đánh giá chất lượng.","Tỷ lệ dự án giao đúng hạn.","Mức nhất quán thuật ngữ khi kiểm tra QA tự động.","Số sự cố bảo mật tài liệu (mục tiêu bằng 0)."],en:["Major errors per 1,000 words on the quality scorecard.","Share of projects delivered on time.","Terminology consistency in automated QA.","Document confidentiality incidents (target zero)."]},day:[{time:"08:00",vi:"Nhận dự án, chạy phân tích bộ nhớ dịch và lập báo giá theo phụ lục đơn giá.",en:"Receive projects, run TM analysis and quote from the rate appendix."},{time:"09:30",vi:"Biên dịch hợp đồng, tra cứu thuật ngữ và ghi câu hỏi cần khách làm rõ.",en:"Translate a contract, research terms and log queries for the client."},{time:"13:30",vi:"Phiên dịch nối tiếp buổi đàm phán kỹ thuật giữa hai đối tác.",en:"Interpret consecutively at a technical negotiation between two partners."},{time:"15:30",vi:"Hiệu đính bản dịch của đồng nghiệp và chạy QA số liệu, đơn vị, thuật ngữ.",en:"Revise a colleague's translation and run QA on numbers, units and terms."},{time:"17:00",vi:"Cập nhật termbase, bộ nhớ dịch và lưu trữ tài liệu theo quy định bảo mật.",en:"Update the termbase and TM and archive files under the security policy."}],mistakes:{vi:["Chỉ tự kiểm tra rồi giao khách, bỏ bước hiệu đính bởi người thứ hai.","Báo giá toàn bộ số từ theo giá đầy đủ, bỏ qua hệ số khớp bộ nhớ dịch đã thỏa thuận.","Đưa tài liệu mật lên công cụ dịch máy công cộng, vi phạm cam kết bảo mật."],en:["Delivering after a self-check only, skipping revision by a second linguist.","Quoting all words at full rate and ignoring the agreed TM match weights.","Uploading confidential documents to public MT tools, breaching confidentiality."]},career:[{vi:"Biên dịch viên tập sự",en:"Junior translator"},{vi:"Biên - phiên dịch viên chuyên ngành",en:"Specialized translator & interpreter"},{vi:"Hiệu đính viên cao cấp & phiên dịch hội nghị",en:"Senior reviser & conference interpreter"},{vi:"Trưởng phòng chất lượng & quản lý dịch vụ ngôn ngữ",en:"Language services & quality manager"}],glossary:[{term:"Revision",vi:"Hiệu đính song ngữ: người thứ hai so bản dịch với bản nguồn để sửa lỗi nghĩa, thuật ngữ, văn phong.",en:"Bilingual examination by a second linguist comparing target and source to fix meaning, terms and style."},{term:"Translation memory",vi:"Bộ nhớ dịch lưu các cặp câu nguồn - đích đã dịch để tái sử dụng.",en:"A database of previously translated source-target segments for reuse."},{term:"Fuzzy match",vi:"Khớp mờ: câu mới giống một phần câu đã có trong bộ nhớ dịch, ví dụ 75-99%.",en:"A new segment partly matching a stored segment, for example 75-99%."},{term:"Termbase",vi:"Cơ sở thuật ngữ đã duyệt kèm định nghĩa và ngữ cảnh sử dụng.",en:"An approved terminology database with definitions and usage context."},{term:"Post-editing",vi:"Hiệu đính bản dịch máy để đạt chất lượng đã thỏa thuận với khách hàng.",en:"Editing machine translation output to reach the quality agreed with the client."}],quiz:[{q:{vi:"Dự án có 5.000 từ mới, 2.000 khớp mờ (hệ số 60%), 1.000 khớp 100% (hệ số 30%), đơn giá 1.000 VND/từ. Báo giá là bao nhiêu?",en:"A project has 5,000 new words, 2,000 fuzzy (60% weight), 1,000 exact (30% weight), rate 1,000 VND per word. What is the quote?"},options:{vi:["8.000.000 VND","6.500.000 VND","7.100.000 VND","5.900.000 VND"],en:["8,000,000 VND","6,500,000 VND","7,100,000 VND","5,900,000 VND"]},answer:1,explain:{vi:"Từ quy đổi = 5.000 + 2.000 x 60% + 1.000 x 30% = 6.500; báo giá = 6.500 x 1.000 = 6.500.000 VND.",en:"Weighted words = 5,000 + 2,000 x 60% + 1,000 x 30% = 6,500; quote = 6,500 x 1,000 = 6,500,000 VND."}},{q:{vi:"Theo ISO 17100, bước nào bắt buộc phải do người khác người dịch thực hiện?",en:"Under ISO 17100, which step must be done by someone other than the translator?"},options:{vi:["Tự kiểm tra","Đếm từ","Rà soát đơn ngữ","Hiệu đính song ngữ (revision)"],en:["Self-check","Word count","Monolingual review","Bilingual revision"]},answer:3,explain:{vi:"ISO 17100 yêu cầu hiệu đính song ngữ bởi người thứ hai; rà soát đơn ngữ là tùy chọn.",en:"ISO 17100 requires bilingual revision by a second person; monolingual review is optional."}},{q:{vi:"Hình thức phiên dịch nào thường cần cabin và tai nghe cho hội nghị lớn?",en:"Which interpreting mode usually needs booths and headsets for large conferences?"},options:{vi:["Phiên dịch song song","Phiên dịch nối tiếp","Dịch nhìn văn bản","Phiên dịch thì thầm"],en:["Simultaneous interpreting","Consecutive interpreting","Sight translation","Whispered interpreting"]},answer:0,explain:{vi:"Phiên dịch song song diễn ra gần như cùng lúc với người nói, cần cabin cách âm và hệ thống tai nghe.",en:"Simultaneous interpreting runs almost in real time and needs soundproof booths and headsets."}},{q:{vi:"Quản lý dự án yêu cầu đưa tài liệu mật lên trang dịch máy miễn phí cho kịp hạn. Bạn làm gì?",en:"The PM asks you to upload a confidential file to a free MT site to meet the deadline. What do you do?"},options:{vi:["Làm theo vì kịp hạn quan trọng nhất","Chỉ đưa lên một nửa tài liệu","Từ chối, báo cáo và đề xuất công cụ được duyệt hoặc xin lùi hạn","Xóa tên khách rồi đưa lên"],en:["Comply since the deadline matters most","Upload only half the document","Refuse, escalate and propose an approved tool or an extension","Remove the client name and upload it"]},answer:2,explain:{vi:"Công cụ công cộng có thể lưu dữ liệu, vi phạm bảo mật; phải dùng công cụ được phê duyệt và minh bạch với khách.",en:"Public tools may store data and breach confidentiality; use approved tools and be transparent with the client."}}],tools_en:["CAT tool with translation memory and termbase","Terminology and number QA tools","Client-approved machine translation tools","Interpreting booth equipment","Text comparison and alignment software","Encrypted document repository"]}},"KK-871":{scenario:{company:"Trường Liên cấp Đồi Thông",supervisor:{name:"Lương Mai Anh",role:{vi:"Tổ trưởng Tin học - Công nghệ",en:"Head of ICT & Technology Department"}},ref_code:"STEM-0726",title:{vi:"Đúng linh kiện. Đúng định luật. Đúng an toàn.",en:"Right component. Right law of physics. Right safety."},brief:{vi:"Bạn duyệt giáo án dự án STEM-0726 “Hệ thống tưới cây tự động” cho lớp 8. Mạch dùng bo vi điều khiển giáo dục, chân tín hiệu xuất 5 V; đèn LED đỏ báo đất khô có điện áp thuận 2,1 V, dòng mong muốn 20 mA. Cảm biến phải đo độ ẩm trong đất để bật bơm mini 5 V. Đối chiếu giáo án nháp với danh mục linh kiện đã duyệt, sửa loại cảm biến và giá trị điện trở hạn dòng cho LED (ôm), rồi lập báo cáo có căn cứ.",en:"You are approving lesson plan STEM-0726 “Automatic plant watering system” for grade 8. The circuit uses an educational microcontroller board with 5 V signal pins; the red “dry soil” LED has a forward voltage of 2.1 V and a target current of 20 mA. The sensor must measure moisture in the soil to switch a 5 V mini pump. Compare the draft plan with the approved parts list, correct the sensor type and the LED current-limiting resistor (ohms), then write an evidence-based report."},reference_title:{vi:"Danh mục linh kiện & phiếu tính mạch đã duyệt · STEM-0726",en:"Approved parts list & circuit worksheet · STEM-0726"},fields:[{id:"SENSOR",label:{vi:"Loại cảm biến trong mạch",en:"Sensor type in the circuit"},initial:"AIR-HUMIDITY",expected:"SOIL-MOISTURE",choices:["AIR-HUMIDITY","LIGHT-LDR","SOIL-MOISTURE"],reference:"Danh mục linh kiện dự án",hint:{vi:"Xác định đại lượng cần đo và môi trường đặt cảm biến: không khí quanh cây hay trong đất?",en:"Identify the quantity to measure and where the sensor sits: in the air around the plant or in the soil?"}},{id:"LED_R_OHM",label:{vi:"Điện trở hạn dòng cho LED (ôm)",en:"LED current-limiting resistor (ohms)"},initial:"250",expected:"145",reference:"Phiếu tính toán mạch LED",ref_value:{vi:"Nguồn 5 V; LED đỏ điện áp thuận 2,1 V; dòng mong muốn 20 mA",en:"Supply 5 V; red LED forward voltage 2.1 V; target current 20 mA"},hint:{vi:"Điện trở chỉ chịu phần điện áp còn lại sau khi trừ điện áp rơi trên LED.",en:"The resistor only drops the voltage left after the LED's forward voltage."}}],sop32:{vi:"Điện trở hạn dòng R = (điện áp nguồn - điện áp thuận của LED) / dòng điện qua LED; đổi mA sang A, ghi kết quả tính bằng ôm trước khi chọn giá trị chuẩn.",en:"Current-limiting resistor R = (supply voltage - LED forward voltage) / LED current; convert mA to A and record the calculated ohms before choosing a standard value."},context:{label:"GIÁO ÁN NHÁP / STEM-0726",metrics:[{label:{vi:"Điện áp chân tín hiệu",en:"Signal pin voltage"},value:"5 V"},{label:{vi:"Điện áp thuận LED",en:"LED forward voltage"},value:"2.1 V"},{label:{vi:"Dòng mong muốn",en:"Target current"},value:"20 mA"}]},crisis:{vi:"Ban tổ chức ngày hội muốn sản phẩm trưng bày “hoành tráng” hơn: “Thay bơm mini 5 V bằng bơm 220 V nối qua rơ-le, cho các em tự đấu dây chiều nay, không kịp chờ thợ điện hay giáo viên giám sát.”",en:"The fair organizers want a more impressive display: “Replace the 5 V mini pump with a 220 V pump through a relay and let the students wire it themselves this afternoon, there is no time to wait for an electrician or teacher supervision.”"},options:{safe:{vi:"Từ chối cho học sinh đấu điện lưới 220 V, giữ mạch điện áp thấp, báo Tổ trưởng; nếu cần bơm lớn thì dùng mô-đun kín đạt chuẩn do thợ điện có chuyên môn lắp và đánh giá rủi ro trước.",en:"Refuse to let students wire 220 V mains, keep the low-voltage circuit and inform the department head; if a bigger pump is needed, a qualified electrician fits a certified enclosed module after a risk assessment."},shortcut:{vi:"Cho học sinh tự đấu bơm 220 V qua rơ-le, nhắc các em cẩn thận là được.",en:"Let students wire the 220 V pump through the relay and just remind them to be careful."},wait:{vi:"Không ý kiến và để ban tổ chức tự quyết định cách lắp bơm.",en:"Say nothing and let the organizers decide how to install the pump."}},questions:{vi:["Vì sao chọn SOIL-MOISTURE và điện trở 145 ôm? Trình bày căn cứ từ danh mục linh kiện và định luật Ohm.","Rủi ro an toàn khi học sinh đấu điện lưới 220 V là gì? Bạn vừa giữ an toàn vừa giữ chất lượng sản phẩm trưng bày thế nào?"],en:["Why choose SOIL-MOISTURE and a 145 ohm resistor? Cite the parts list and Ohm's law.","What are the safety risks of students wiring 220 V mains? How do you keep both safety and a quality display?"]},hints:{vi:["Đặt giáo án nháp cạnh danh mục linh kiện và đối chiếu đại lượng cảm biến đo được.","Áp dụng SOP mục 3.2: trừ điện áp thuận của LED khỏi điện áp nguồn rồi chia cho dòng điện tính bằng A.","Đọc lại SOP mục 4.2: học sinh chỉ làm việc với mạch điện áp thấp; mọi đề xuất dùng điện lưới phải được báo cáo và đánh giá rủi ro."],en:["Place the draft plan next to the parts list and check which quantity each sensor measures.","Apply SOP 3.2: subtract the LED forward voltage from the supply, then divide by the current in amps.","Re-read SOP 4.2: students work only on low-voltage circuits; any mains proposal must be escalated and risk-assessed."]}},learning:{summary:{vi:"Giáo viên Tin học và STEM dạy năng lực số, lập trình, tư duy máy tính và tổ chức dự án liên môn khoa học, công nghệ, kỹ thuật, toán học. Giáo viên thiết kế bài học theo quy trình thiết kế kỹ thuật, hướng dẫn học sinh làm mẫu thử với vi điều khiển, cảm biến, đánh giá bằng rubric và bảo đảm an toàn điện, an toàn số trong phòng học.",en:"An ICT and STEM teacher teaches digital competence, programming and computational thinking and runs interdisciplinary science, technology, engineering and math projects. The teacher designs lessons around the engineering design process, guides students to build prototypes with microcontrollers and sensors, assesses with rubrics and ensures electrical and online safety in class."},responsibilities:{vi:["Soạn kế hoạch bài dạy Tin học theo chương trình giáo dục phổ thông và yêu cầu cần đạt.","Thiết kế dự án STEM liên môn với mục tiêu, tiêu chí sản phẩm và rubric đánh giá rõ ràng.","Chuẩn bị, kiểm tra linh kiện, thiết bị và phiếu tính toán mạch trước giờ thực hành.","Hướng dẫn học sinh lập trình, lắp mạch, thử nghiệm và cải tiến mẫu thử.","Giáo dục an toàn điện, an toàn mạng và công dân số; quản lý phòng máy, phòng STEM."],en:["Plan ICT lessons aligned with the national curriculum and required learning outcomes.","Design interdisciplinary STEM projects with clear goals, product criteria and rubrics.","Prepare and check components, equipment and circuit worksheets before practical sessions.","Guide students to program, build circuits, test and improve prototypes.","Teach electrical safety, online safety and digital citizenship; manage the computer and STEM labs."]},competencies:[{name:{vi:"Kiến thức khoa học - kỹ thuật",en:"Science & engineering knowledge"},desc:{vi:"Vận dụng chính xác định luật Ohm, nguyên lý cảm biến, cơ cấu chấp hành và lập trình nhúng cơ bản.",en:"Apply Ohm's law, sensor principles, actuators and basic embedded programming accurately."}},{name:{vi:"Thiết kế bài học STEM",en:"STEM lesson design"},desc:{vi:"Xây dựng vấn đề thực tiễn, tiến trình theo quy trình thiết kế kỹ thuật và tiêu chí sản phẩm.",en:"Frame real problems, sequence work along the engineering design process and set product criteria."}},{name:{vi:"Dạy lập trình & tư duy máy tính",en:"Teaching programming & computational thinking"},desc:{vi:"Dẫn dắt học sinh phân rã, trừu tượng hóa, viết thuật toán và gỡ lỗi chương trình.",en:"Lead students to decompose, abstract, write algorithms and debug programs."}},{name:{vi:"Đánh giá theo năng lực",en:"Competency-based assessment"},desc:{vi:"Dùng rubric, nhật ký dự án và trình bày sản phẩm để đánh giá quá trình và kết quả.",en:"Use rubrics, project logs and presentations to assess both process and product."}},{name:{vi:"An toàn & trách nhiệm",en:"Safety & responsibility"},desc:{vi:"Giữ học sinh làm việc với điện áp thấp, kiểm tra thiết bị và hướng dẫn ứng xử an toàn trên mạng.",en:"Keep students on low voltage, inspect equipment and teach safe online behavior."}}],knowledge:{vi:["Chương trình giáo dục phổ thông 2018 ban hành kèm Thông tư 32/2018/TT-BGDĐT, gồm chương trình môn Tin học và Công nghệ.","Hướng dẫn triển khai giáo dục STEM trong giáo dục trung học (Công văn 3089/BGDĐT-GDTrH năm 2020): bài học STEM, trải nghiệm STEM, nghiên cứu khoa học kỹ thuật.","Quy trình thiết kế kỹ thuật: xác định vấn đề, nghiên cứu, đề xuất giải pháp, làm mẫu thử, thử nghiệm, cải tiến, chia sẻ.","Định luật Ohm U = I x R, điện áp thuận của LED, giới hạn dòng chân tín hiệu vi điều khiển.","Tư duy máy tính: phân rã, nhận dạng mẫu, trừu tượng hóa, thuật toán; an toàn mạng và công dân số."],en:["The 2018 General Education Curriculum issued with Circular 32/2018/TT-BGDDT, including the ICT and Technology subject programs.","Guidance on STEM education in secondary schools (Official Letter 3089/BGDDT-GDTrH, 2020): STEM lessons, STEM experiences and science and engineering research.","Engineering design process: define the problem, research, propose solutions, prototype, test, improve and share.","Ohm's law V = I x R, LED forward voltage and microcontroller pin current limits.","Computational thinking: decomposition, pattern recognition, abstraction and algorithms; online safety and digital citizenship."]},tools:["Bo mạch vi điều khiển giáo dục","Môi trường lập trình kéo thả khối lệnh","Đồng hồ vạn năng","Phần mềm mô phỏng mạch điện","Máy in 3D","Hệ thống quản lý lớp học trực tuyến"],kpis:{vi:["Tỷ lệ học sinh đạt yêu cầu cần đạt của chủ đề theo rubric.","Tỷ lệ nhóm hoàn thành mẫu thử hoạt động đúng tiêu chí.","Số sự cố an toàn điện, thiết bị trong phòng thực hành (mục tiêu bằng 0).","Mức độ hứng thú, tự tin của học sinh qua khảo sát cuối dự án."],en:["Share of students meeting the topic's required outcomes on the rubric.","Share of teams completing a working prototype that meets criteria.","Electrical or equipment safety incidents in the lab (target zero).","Student engagement and confidence in the end-of-project survey."]},day:[{time:"07:15",vi:"Kiểm tra phòng máy, bo mạch, nguồn điện áp thấp và bộ linh kiện của từng nhóm.",en:"Check the computer lab, boards, low-voltage supplies and each team's kit."},{time:"08:00",vi:"Dạy tiết Tin học về cấu trúc lặp, cho học sinh viết và gỡ lỗi chương trình.",en:"Teach an ICT lesson on loops and have students write and debug programs."},{time:"10:00",vi:"Hướng dẫn tiết STEM: đo độ ẩm đất, đọc giá trị cảm biến và lập ngưỡng bật bơm.",en:"Lead a STEM session: measure soil moisture, read sensor values and set the pump threshold."},{time:"14:00",vi:"Họp tổ chuyên môn, rà soát giáo án dự án và phiếu tính toán mạch.",en:"Attend the department meeting and review project plans and circuit worksheets."},{time:"16:00",vi:"Chấm nhật ký dự án theo rubric và phản hồi cho từng nhóm.",en:"Grade project logs with the rubric and give each team feedback."}],mistakes:{vi:["Chọn cảm biến độ ẩm không khí cho bài toán đo độ ẩm đất, khiến hệ thống tưới hoạt động sai.","Tính điện trở bằng điện áp nguồn chia dòng điện, quên trừ điện áp thuận của LED.","Cho học sinh tự đấu điện lưới vì áp lực trưng bày, bỏ qua đánh giá rủi ro."],en:["Choosing an air humidity sensor for a soil moisture problem, so the watering system misbehaves.","Computing the resistor as supply voltage over current without subtracting the LED forward voltage.","Letting students wire mains power under display pressure, skipping the risk assessment."]},career:[{vi:"Giáo viên Tin học tập sự",en:"Probationary ICT teacher"},{vi:"Giáo viên Tin học & STEM",en:"ICT & STEM teacher"},{vi:"Tổ trưởng chuyên môn Tin học - Công nghệ",en:"Head of ICT & Technology"},{vi:"Điều phối viên giáo dục STEM & chuyển đổi số nhà trường",en:"STEM & digital transformation coordinator"}],glossary:[{term:"Forward voltage",vi:"Điện áp thuận: điện áp rơi trên LED khi LED dẫn điện và phát sáng.",en:"The voltage dropped across an LED when it conducts and lights up."},{term:"Microcontroller",vi:"Vi điều khiển: máy tính nhỏ trên một chip, đọc cảm biến và điều khiển thiết bị theo chương trình.",en:"A small computer on a chip that reads sensors and controls devices by program."},{term:"Prototype",vi:"Mẫu thử: phiên bản ban đầu của sản phẩm để kiểm tra ý tưởng và cải tiến.",en:"An early version of a product used to test the idea and improve it."},{term:"Rubric",vi:"Bảng tiêu chí đánh giá mô tả các mức chất lượng cho từng tiêu chí.",en:"A scoring guide describing quality levels for each criterion."},{term:"Decomposition",vi:"Phân rã: chia một bài toán lớn thành các phần nhỏ dễ giải quyết hơn.",en:"Breaking a big problem into smaller, easier parts."}],quiz:[{q:{vi:"LED trắng có điện áp thuận 3,0 V, nguồn 5 V, dòng mong muốn 10 mA. Điện trở hạn dòng tính được là bao nhiêu?",en:"A white LED has a 3.0 V forward voltage, a 5 V supply and a 10 mA target current. What is the calculated resistor?"},options:{vi:["500 ôm","300 ôm","200 ôm","50 ôm"],en:["500 ohms","300 ohms","200 ohms","50 ohms"]},answer:2,explain:{vi:"R = (5 - 3,0) / 0,010 = 200 ôm.",en:"R = (5 - 3.0) / 0.010 = 200 ohms."}},{q:{vi:"Chia dự án tưới cây thành các phần: đọc cảm biến, so sánh ngưỡng, bật bơm. Đây là kỹ năng nào của tư duy máy tính?",en:"Splitting the watering project into reading the sensor, comparing a threshold and switching the pump is which computational thinking skill?"},options:{vi:["Phân rã","Trừu tượng hóa","Nhận dạng mẫu","Gỡ lỗi"],en:["Decomposition","Abstraction","Pattern recognition","Debugging"]},answer:0,explain:{vi:"Phân rã là chia bài toán lớn thành các phần nhỏ có thể giải riêng.",en:"Decomposition breaks a big problem into smaller parts that can be solved separately."}},{q:{vi:"Bước đầu tiên của quy trình thiết kế kỹ thuật trong bài học STEM là gì?",en:"What is the first step of the engineering design process in a STEM lesson?"},options:{vi:["Làm mẫu thử ngay","Xác định vấn đề và tiêu chí sản phẩm","Chấm điểm sản phẩm","Mua linh kiện"],en:["Build a prototype immediately","Define the problem and product criteria","Grade the product","Buy components"]},answer:1,explain:{vi:"Phải xác định rõ vấn đề và tiêu chí trước khi nghiên cứu, đề xuất và làm mẫu thử.",en:"The problem and criteria must be defined before research, ideas and prototyping."}},{q:{vi:"Ban tổ chức muốn học sinh tự đấu bơm 220 V cho kịp ngày hội. Giáo viên nên làm gì?",en:"Organizers want students to wire a 220 V pump themselves for the fair. What should the teacher do?"},options:{vi:["Đồng ý nếu học sinh đeo găng tay","Tự đấu thay học sinh mà không báo ai","Để học sinh tự quyết","Từ chối, giữ mạch điện áp thấp và báo cáo để có phương án an toàn"],en:["Agree if students wear gloves","Wire it yourself without telling anyone","Let students decide","Refuse, keep low voltage and escalate for a safe solution"]},answer:3,explain:{vi:"Điện lưới có nguy cơ điện giật, cháy nổ; học sinh chỉ làm việc với điện áp thấp, phương án khác phải được đánh giá rủi ro.",en:"Mains power risks electric shock and fire; students use low voltage only, and any alternative needs a risk assessment."}}],tools_en:["Educational microcontroller boards","Block-based visual programming environment","Multimeter","Circuit simulation software","3D printer","Online classroom management system"]}},"KK-872":{scenario:{company:"Trường Đại học Kim Ngân Hà",supervisor:{name:"Mạc Hữu Phong",role:{vi:"Giám đốc Trung tâm Khảo thí và Đảm bảo chất lượng",en:"Director of Testing & Quality Assurance"}},ref_code:"QA-8840",title:{vi:"Đúng thống kê. Đúng quyết định. Đúng minh chứng.",en:"Right statistics. Right decision. Right evidence."},brief:{vi:"Bạn rà soát báo cáo phân tích câu hỏi QA-8840 của đề thi kết thúc học phần có 200 thí sinh. Nhóm cao và nhóm thấp mỗi nhóm lấy 27% thí sinh, tức 54 người. Câu 14: nhóm cao có 41 người làm đúng, nhóm thấp có 20 người. Câu 27 có độ phân biệt âm (-0,12). Đối chiếu bản báo cáo nháp với quy trình phân tích đề thi đã duyệt, sửa quyết định xử lý câu 27 và độ phân biệt D của câu 14, rồi lập báo cáo có căn cứ.",en:"You are reviewing item analysis report QA-8840 for a final course exam taken by 200 candidates. The upper and lower groups each take 27% of candidates, that is 54 people. Item 14: 41 people in the upper group and 20 in the lower group answered correctly. Item 27 has a negative discrimination index (-0.12). Compare the draft report with the approved exam analysis procedure, correct the decision for item 27 and the discrimination index D of item 14, then write an evidence-based report."},reference_title:{vi:"Quy trình phân tích câu hỏi thi đã duyệt · QA-8840",en:"Approved item analysis procedure · QA-8840"},fields:[{id:"ITEM27_ACT",label:{vi:"Quyết định xử lý câu 27",en:"Decision for item 27"},initial:"KEEP",expected:"EXCLUDE",choices:["KEEP","REVISE","EXCLUDE"],reference:"Bảng quyết định theo độ phân biệt",hint:{vi:"Độ phân biệt âm nghĩa là nhóm thấp làm đúng nhiều hơn nhóm cao, thường do sai đáp án hoặc câu hỏi gây hiểu nhầm.",en:"A negative index means the lower group outscored the upper group, often due to a wrong key or a misleading item."}},{id:"D_ITEM14",label:{vi:"Độ phân biệt D của câu 14",en:"Discrimination index D of item 14"},initial:"0.19",expected:"0.39",reference:"Bảng thống kê câu hỏi",ref_value:{vi:"Mỗi nhóm 54 thí sinh; câu 14: nhóm cao đúng 41, nhóm thấp đúng 20",en:"54 candidates per group; item 14: upper correct 41, lower correct 20"},hint:{vi:"Kiểm tra mẫu số: công thức dùng số thí sinh của một nhóm, không phải tổng hai nhóm.",en:"Check the denominator: the formula uses one group's size, not both groups combined."}}],sop32:{vi:"D = (số đúng nhóm cao - số đúng nhóm thấp) / số thí sinh của một nhóm, làm tròn 2 chữ số thập phân. D từ 0,30: giữ; 0,20-0,29: sửa; dưới 0,20 hoặc âm: loại khỏi tính điểm và rà soát đáp án.",en:"D = (upper group correct - lower group correct) / size of one group, rounded to 2 decimals. D of 0.30 or more: keep; 0.20-0.29: revise; below 0.20 or negative: exclude from scoring and review the key."},context:{label:"PHẦN MỀM PHÂN TÍCH ĐỀ / QA-8840",metrics:[{label:{vi:"Số thí sinh",en:"Candidates"},value:"200"},{label:{vi:"Cỡ mỗi nhóm (27%)",en:"Group size (27%)"},value:"54"},{label:{vi:"D câu 27",en:"Item 27 D"},value:"-0.12"}]},crisis:{vi:"Phòng Đào tạo nhắn: “Sắp đánh giá ngoài rồi. Em soạn giúp biên bản họp rà soát đề thi cho 3 học kỳ trước, dù thực tế chưa họp, ghi lùi ngày và xin chữ ký bổ sung là được.”",en:"The Academic Affairs office writes: “External assessment is coming. Please draft exam review meeting minutes for the past 3 semesters, even though no meetings were held, backdate them and collect signatures afterwards.”"},options:{safe:{vi:"Từ chối lập minh chứng khống, báo Giám đốc Trung tâm; ghi nhận trung thực điểm còn thiếu trong báo cáo tự đánh giá, tổ chức họp rà soát thật ngay và lập kế hoạch cải tiến có thời hạn.",en:"Refuse to fabricate evidence and inform the Center Director; record the gap honestly in the self-assessment report, hold a real review meeting now and set a time-bound improvement plan."},shortcut:{vi:"Soạn biên bản lùi ngày cho kịp đoàn đánh giá, sau này sẽ họp bù cho đủ thủ tục.",en:"Draft backdated minutes for the assessors and hold catch-up meetings later to complete the formalities."},wait:{vi:"Im lặng, không soạn cũng không báo cáo, chờ đoàn đánh giá tự phát hiện.",en:"Stay silent, neither draft nor report, and wait for the assessors to notice."}},questions:{vi:["Vì sao câu 27 phải EXCLUDE và D của câu 14 là 0.39? Trình bày phép tính và bảng quyết định.","Lập minh chứng khống cho kiểm định gây hậu quả gì? Bạn xử lý điểm còn thiếu trong hệ thống đảm bảo chất lượng thế nào?"],en:["Why must item 27 be EXCLUDE and why is item 14's D equal to 0.39? Show the calculation and decision table.","What are the consequences of fabricating accreditation evidence? How do you handle the gap in the quality system?"]},hints:{vi:["Đặt báo cáo nháp cạnh bảng quyết định và kiểm tra dấu của độ phân biệt từng câu.","Áp dụng SOP mục 3.2: chia hiệu số đúng của hai nhóm cho cỡ của MỘT nhóm.","Đọc lại SOP mục 4.2: minh chứng kiểm định phải phản ánh hoạt động có thật; thiếu sót được báo cáo và đưa vào kế hoạch cải tiến."],en:["Place the draft report next to the decision table and check the sign of each item's index.","Apply SOP 3.2: divide the difference in correct answers by the size of ONE group.","Re-read SOP 4.2: accreditation evidence must reflect real activities; gaps are reported and put into an improvement plan."]}},learning:{summary:{vi:"Chuyên viên khảo thí và đảm bảo chất lượng giáo dục xây dựng ngân hàng câu hỏi, ma trận đề, tổ chức thi, phân tích thống kê câu hỏi và độ tin cậy, đồng thời vận hành hệ thống đảm bảo chất lượng bên trong và chuẩn bị tự đánh giá, đánh giá ngoài. Nghề đòi hỏi nền tảng đo lường giáo dục, thống kê, hiểu khung kiểm định và sự liêm chính tuyệt đối với dữ liệu, minh chứng.",en:"An assessment and education quality assurance specialist builds item banks and test blueprints, runs exams, analyzes item statistics and reliability, operates the internal quality assurance system and prepares self-assessment and external review. The role requires a foundation in educational measurement, statistics, knowledge of accreditation frameworks and absolute integrity with data and evidence."},responsibilities:{vi:["Xây dựng ma trận đề, bảng đặc tả liên kết chuẩn đầu ra với câu hỏi thi.","Quản lý ngân hàng câu hỏi, tổ chức thẩm định, thử nghiệm và hiệu chỉnh câu hỏi.","Phân tích độ khó, độ phân biệt, độ tin cậy sau mỗi kỳ thi và đề xuất xử lý câu hỏi.","Vận hành quy trình đảm bảo chất lượng bên trong, khảo sát các bên liên quan và theo dõi cải tiến.","Chuẩn bị báo cáo tự đánh giá, quản lý minh chứng và làm việc với đoàn đánh giá ngoài."],en:["Build test blueprints and specification tables linking learning outcomes to items.","Manage the item bank and organize item review, piloting and calibration.","Analyze difficulty, discrimination and reliability after each exam and propose item actions.","Run internal quality assurance processes, stakeholder surveys and improvement tracking.","Prepare self-assessment reports, manage evidence and work with external review panels."]},competencies:[{name:{vi:"Đo lường & đánh giá giáo dục",en:"Educational measurement"},desc:{vi:"Thiết kế đề thi giá trị, tin cậy, công bằng và khớp chuẩn đầu ra.",en:"Design valid, reliable, fair tests aligned with learning outcomes."}},{name:{vi:"Phân tích thống kê câu hỏi",en:"Item statistics analysis"},desc:{vi:"Tính và diễn giải độ khó, độ phân biệt, Cronbach's alpha và tham số IRT.",en:"Compute and interpret difficulty, discrimination, Cronbach's alpha and IRT parameters."}},{name:{vi:"Hiểu khung kiểm định",en:"Accreditation frameworks"},desc:{vi:"Nắm tiêu chuẩn, tiêu chí kiểm định trong nước và AUN-QA, liên kết minh chứng đúng tiêu chí.",en:"Know national standards and AUN-QA criteria and map evidence to the right criterion."}},{name:{vi:"Cải tiến liên tục",en:"Continuous improvement"},desc:{vi:"Vận dụng chu trình PDCA, theo dõi kế hoạch cải tiến và báo cáo tiến độ.",en:"Apply the PDCA cycle, track improvement plans and report progress."}},{name:{vi:"Liêm chính dữ liệu",en:"Data integrity"},desc:{vi:"Bảo mật đề thi, không chỉnh điểm, không lập minh chứng khống và báo cáo trung thực.",en:"Keep exams secure, never alter scores or fabricate evidence and report honestly."}}],knowledge:{vi:["Luật Giáo dục đại học số 08/2012/QH13, sửa đổi bởi Luật số 34/2018/QH14, về đảm bảo và kiểm định chất lượng.","Bộ tiêu chuẩn kiểm định chất lượng cơ sở giáo dục và chương trình đào tạo do Bộ GD&ĐT ban hành; khung AUN-QA của mạng lưới đại học ASEAN.","Lý thuyết trắc nghiệm cổ điển: độ khó p, độ phân biệt D, tương quan điểm câu - tổng và độ tin cậy Cronbach's alpha.","Lý thuyết ứng đáp câu hỏi (IRT), mô hình Rasch và cân bằng đề tương đương.","Bộ chuẩn Standards for Educational and Psychological Testing (AERA, APA, NCME, 2014) về giá trị, độ tin cậy và công bằng."],en:["Higher Education Law No. 08/2012/QH13, amended by Law No. 34/2018/QH14, on quality assurance and accreditation.","National accreditation standards for institutions and programs issued by the Ministry of Education and Training; the ASEAN University Network AUN-QA framework.","Classical test theory: difficulty p, discrimination D, item-total correlation and Cronbach's alpha reliability.","Item response theory (IRT), the Rasch model and test equating.","The Standards for Educational and Psychological Testing (AERA, APA, NCME, 2014) on validity, reliability and fairness."]},tools:["Phần mềm phân tích câu hỏi CTT và IRT","Hệ thống ngân hàng câu hỏi thi","Phần mềm thống kê","Hệ thống chấm trắc nghiệm quang học (OMR)","Phần mềm quản lý minh chứng kiểm định","Công cụ khảo sát trực tuyến"],kpis:{vi:["Tỷ lệ câu hỏi trong ngân hàng đạt độ phân biệt từ 0,30.","Độ tin cậy Cronbach's alpha của đề thi (mục tiêu mô phỏng từ 0,80).","Tỷ lệ kế hoạch cải tiến hoàn thành đúng hạn.","Số sự cố lộ đề, sai sót điểm và minh chứng không xác thực (mục tiêu bằng 0)."],en:["Share of bank items with discrimination of 0.30 or more.","Exam Cronbach's alpha reliability (training target 0.80 or more).","Share of improvement actions completed on time.","Exam leaks, scoring errors and non-genuine evidence (target zero)."]},day:[{time:"08:00",vi:"Nhận dữ liệu chấm thi, kiểm tra tính toàn vẹn tệp điểm và nhật ký truy cập.",en:"Receive scoring data and check score file integrity and access logs."},{time:"09:30",vi:"Chạy phân tích câu hỏi, đánh dấu câu có độ phân biệt thấp hoặc âm.",en:"Run item analysis and flag items with low or negative discrimination."},{time:"13:30",vi:"Họp với giảng viên ra đề, rà soát đáp án và thống nhất xử lý từng câu.",en:"Meet item writers, review keys and agree on actions for each item."},{time:"15:30",vi:"Cập nhật minh chứng, đối chiếu tiêu chí và tiến độ kế hoạch cải tiến.",en:"Update evidence, map it to criteria and track improvement plan progress."},{time:"17:00",vi:"Hoàn thiện báo cáo chất lượng đề thi gửi Hội đồng đảm bảo chất lượng.",en:"Finalize the exam quality report for the quality assurance council."}],mistakes:{vi:["Chia hiệu số đúng cho tổng hai nhóm thay vì cỡ một nhóm, làm độ phân biệt thấp đi một nửa.","Giữ câu có độ phân biệt âm mà không rà soát đáp án, gây thiệt thòi cho thí sinh giỏi.","Lập biên bản, minh chứng lùi ngày để đối phó kiểm định, làm sai lệch hệ thống chất lượng."],en:["Dividing by both groups combined instead of one group, halving the discrimination index.","Keeping a negatively discriminating item without checking the key, penalizing strong candidates.","Backdating minutes or evidence for accreditation, corrupting the quality system."]},career:[{vi:"Chuyên viên khảo thí",en:"Assessment officer"},{vi:"Chuyên viên đo lường & đảm bảo chất lượng",en:"Measurement & QA specialist"},{vi:"Trưởng phòng khảo thí & kiểm định",en:"Head of testing & accreditation"},{vi:"Giám đốc trung tâm khảo thí và đảm bảo chất lượng",en:"Director of testing & quality assurance"}],glossary:[{term:"Item difficulty (p)",vi:"Độ khó: tỷ lệ thí sinh trả lời đúng câu hỏi, p càng cao câu càng dễ.",en:"Share of candidates answering an item correctly; a higher p means an easier item."},{term:"Discrimination index (D)",vi:"Độ phân biệt: mức câu hỏi phân biệt được thí sinh giỏi và kém, tính từ nhóm cao và nhóm thấp.",en:"How well an item separates strong and weak candidates, computed from upper and lower groups."},{term:"Cronbach's alpha",vi:"Hệ số đo độ nhất quán nội tại, phản ánh độ tin cậy của bài thi.",en:"A coefficient of internal consistency reflecting test reliability."},{term:"Test blueprint",vi:"Ma trận đề, bảng đặc tả phân bố câu hỏi theo nội dung, chuẩn đầu ra và mức nhận thức.",en:"A table distributing items by content, learning outcome and cognitive level."},{term:"Self-assessment report",vi:"Báo cáo tự đánh giá của cơ sở hoặc chương trình theo bộ tiêu chuẩn trước đánh giá ngoài.",en:"An institution or program's report against standards prepared before external review."}],quiz:[{q:{vi:"Mỗi nhóm có 40 thí sinh; nhóm cao 30 người đúng, nhóm thấp 14 người đúng. Độ phân biệt D là bao nhiêu?",en:"Each group has 40 candidates; 30 in the upper group and 14 in the lower group answered correctly. What is D?"},options:{vi:["0,20","0,40","0,55","0,80"],en:["0.20","0.40","0.55","0.80"]},answer:1,explain:{vi:"D = (30 - 14) / 40 = 0,40, câu hỏi phân biệt rất tốt.",en:"D = (30 - 14) / 40 = 0.40, a very good discriminating item."}},{q:{vi:"Câu hỏi có độ khó p = 0,85 nghĩa là gì?",en:"What does an item difficulty of p = 0.85 mean?"},options:{vi:["Câu rất khó","85% thí sinh làm sai","Câu phân biệt tốt","85% thí sinh làm đúng, câu tương đối dễ"],en:["A very hard item","85% answered wrongly","A well-discriminating item","85% answered correctly, a fairly easy item"]},answer:3,explain:{vi:"Độ khó p là tỷ lệ trả lời đúng; p = 0,85 cho thấy câu dễ với nhóm thí sinh này.",en:"Difficulty p is the share answering correctly; p = 0.85 shows an easy item for this group."}},{q:{vi:"Được yêu cầu soạn biên bản họp lùi ngày để có minh chứng kiểm định. Bạn làm gì?",en:"You are asked to draft backdated meeting minutes as accreditation evidence. What do you do?"},options:{vi:["Từ chối, báo cáo và ghi nhận trung thực điểm thiếu kèm kế hoạch cải tiến","Soạn vì ai cũng làm vậy","Soạn nhưng không ký tên","Chờ đoàn đánh giá tự phát hiện"],en:["Refuse, escalate and record the gap honestly with an improvement plan","Draft them since everyone does","Draft them but do not sign","Wait for the assessors to notice"]},answer:0,explain:{vi:"Minh chứng khống làm mất giá trị kiểm định; cách đúng là minh bạch điểm yếu và cải tiến thật.",en:"Fabricated evidence voids accreditation; the right way is transparency about weaknesses and real improvement."}},{q:{vi:"Hệ số Cronbach's alpha dùng để đánh giá điều gì?",en:"What does Cronbach's alpha evaluate?"},options:{vi:["Độ khó trung bình của đề","Tỷ lệ thí sinh đạt","Độ nhất quán nội tại, tức độ tin cậy của bài thi","Thời gian làm bài"],en:["Average test difficulty","Pass rate","Internal consistency, that is test reliability","Time on test"]},answer:2,explain:{vi:"Alpha phản ánh mức các câu hỏi cùng đo một năng lực một cách nhất quán.",en:"Alpha reflects how consistently the items measure the same construct."}}],tools_en:["CTT and IRT item analysis software","Exam item bank system","Statistical software","Optical mark recognition (OMR) system","Accreditation evidence management software","Online survey tool"]}},"KK-873":{scenario:{company:"Thanh Vân Precision Manufacturing",supervisor:{name:"Châu Gia Huy",role:{vi:"Giám đốc Nhân sự",en:"HR Director"}},ref_code:"TRN-3195",title:{vi:"Đúng cấp độ đánh giá. Đúng ROI. Đúng hồ sơ huấn luyện.",en:"Right evaluation level. Right ROI. Right training records."},brief:{vi:"Chương trình TRN-3195 đào tạo 5S và an toàn cho 120 tổ trưởng sản xuất đã kết thúc 6 tháng. Chi phí trực tiếp 150 triệu VND, chi phí thời gian học viên quy lương 90 triệu VND; lợi ích tiền tệ đã tách riêng tác động của đào tạo là 516 triệu VND (số liệu mô phỏng). Chỉ số 2 đo tỷ lệ tổ trưởng áp dụng đúng 5S khi quan sát tại xưởng sau 60 ngày. Đối chiếu báo cáo nháp với khung đánh giá đã duyệt, sửa cấp độ của chỉ số 2 và ROI (%), rồi lập báo cáo có căn cứ.",en:"Program TRN-3195, training 120 production team leaders in 5S and safety, ended 6 months ago. Direct costs were 150 million VND and participant time at wage cost 90 million VND; monetary benefits isolated to the training are 516 million VND (training data). Metric 2 measures the share of team leaders correctly applying 5S when observed on the shop floor after 60 days. Compare the draft report with the approved evaluation framework, correct the level of metric 2 and the ROI (%), then write an evidence-based report."},reference_title:{vi:"Khung đánh giá hiệu quả đào tạo đã duyệt · TRN-3195",en:"Approved training evaluation framework · TRN-3195"},fields:[{id:"EVAL_LVL",label:{vi:"Cấp độ đánh giá của chỉ số 2",en:"Evaluation level of metric 2"},initial:"L2-LEARNING",expected:"L3-BEHAVIOR",choices:["L2-LEARNING","L3-BEHAVIOR","L4-RESULTS"],reference:"Ma trận chỉ số theo Kirkpatrick",hint:{vi:"Hỏi: chỉ số đo kiến thức trong lớp, hành vi áp dụng tại nơi làm việc hay kết quả kinh doanh?",en:"Ask: does the metric measure classroom knowledge, on-the-job behavior or business results?"}},{id:"ROI_PCT",label:{vi:"ROI của chương trình (%)",en:"Program ROI (%)"},initial:"215",expected:"115",reference:"Bảng tính ROI chương trình",ref_value:{vi:"Chi phí trực tiếp 150 triệu; thời gian học viên 90 triệu; lợi ích tiền tệ 516 triệu VND",en:"Direct costs 150 million; participant time 90 million; monetary benefits 516 million VND"},hint:{vi:"ROI dùng lợi ích ròng, tức lợi ích trừ chi phí; lợi ích chia chi phí là một chỉ số khác.",en:"ROI uses net benefits, that is benefits minus costs; benefits over costs is a different ratio."}}],sop32:{vi:"ROI (%) = (lợi ích tiền tệ - tổng chi phí đầy đủ) / tổng chi phí đầy đủ x 100; tổng chi phí gồm chi phí trực tiếp và thời gian học viên. Không nhầm với tỷ số lợi ích/chi phí (BCR).",en:"ROI (%) = (monetary benefits - fully loaded costs) / fully loaded costs x 100; costs include direct costs and participant time. Do not confuse it with the benefit-cost ratio (BCR)."},context:{label:"LMS & BÁO CÁO ĐÀO TẠO / TRN-3195",metrics:[{label:{vi:"Số học viên",en:"Participants"},value:"120"},{label:{vi:"Tổng chi phí mô phỏng",en:"Training total costs"},value:"240,000,000 VND"},{label:{vi:"Lợi ích tiền tệ mô phỏng",en:"Training monetary benefits"},value:"516,000,000 VND"}]},crisis:{vi:"Nhà thầu huấn luyện an toàn bên ngoài đề nghị: “Bên em ký danh sách điểm danh và cấp giấy chứng nhận huấn luyện an toàn cho 40 công nhân chưa học, kịp đợt thanh tra lao động tuần sau. Có chút quà cảm ơn anh chị.”",en:"The external safety training contractor offers: “We will sign the attendance list and issue safety training certificates for 40 workers who have not attended, in time for next week's labor inspection. There is a small thank-you gift for you.”"},options:{safe:{vi:"Từ chối hồ sơ khống và quà, báo Giám đốc Nhân sự và bộ phận tuân thủ; tổ chức ngay lớp huấn luyện bù có kiểm tra thật và báo cáo trung thực tình trạng với đoàn thanh tra.",en:"Refuse the fake records and the gift, inform the HR Director and compliance; schedule a real make-up course with a genuine test right away and report the status honestly to inspectors."},shortcut:{vi:"Nhận danh sách và chứng nhận cho kịp thanh tra, sau đợt thanh tra sẽ cho công nhân học bù.",en:"Accept the list and certificates to pass the inspection and let workers attend a make-up course afterwards."},wait:{vi:"Không trả lời nhà thầu và chờ đến khi đoàn thanh tra tới rồi tính tiếp.",en:"Do not reply to the contractor and wait until the inspectors arrive."}},questions:{vi:["Vì sao chỉ số 2 thuộc L3-BEHAVIOR và ROI đúng là 115%? Trình bày công thức và phân biệt với BCR.","Hồ sơ huấn luyện an toàn khống gây rủi ro gì cho người lao động và doanh nghiệp? Bạn xử lý đề nghị của nhà thầu thế nào?"],en:["Why is metric 2 L3-BEHAVIOR and why is the correct ROI 115%? Show the formula and how it differs from BCR.","What risks do fake safety training records create for workers and the company? How do you handle the contractor's offer?"]},hints:{vi:["Đặt báo cáo nháp cạnh ma trận chỉ số và đối chiếu nơi, thời điểm đo của chỉ số 2.","Áp dụng SOP mục 3.2: cộng đủ chi phí trực tiếp và thời gian học viên, lấy lợi ích trừ chi phí rồi mới chia.","Đọc lại SOP mục 4.2: hồ sơ huấn luyện phải phản ánh đào tạo thật; mọi đề nghị kèm quà phải được báo cáo."],en:["Place the draft report next to the metric matrix and check where and when metric 2 is measured.","Apply SOP 3.2: add direct and participant time costs, subtract them from benefits, then divide.","Re-read SOP 4.2: training records must reflect real training; any offer with a gift must be reported."]}},learning:{summary:{vi:"Quản lý đào tạo doanh nghiệp xây dựng chiến lược học tập gắn với mục tiêu kinh doanh: phân tích nhu cầu, thiết kế lộ trình năng lực, vận hành chương trình nội bộ và thuê ngoài, quản lý ngân sách, đánh giá hiệu quả đến cấp độ kết quả và ROI. Vị trí đòi hỏi tư duy hệ thống, năng lực điều phối nhiều bên, hiểu luật lao động, an toàn lao động và chuẩn mực trung thực với hồ sơ đào tạo.",en:"A corporate training manager builds a learning strategy tied to business goals: analyzing needs, designing competency paths, running internal and outsourced programs, managing the budget and evaluating impact up to results and ROI. The role requires systems thinking, multi-party coordination, knowledge of labor and occupational safety law and strict honesty with training records."},responsibilities:{vi:["Phân tích nhu cầu đào tạo ở cấp tổ chức, công việc và cá nhân cùng các trưởng bộ phận.","Lập kế hoạch, ngân sách đào tạo năm và lộ trình năng lực cho từng nhóm vị trí.","Vận hành chương trình nội bộ, lựa chọn và giám sát nhà cung cấp đào tạo bên ngoài.","Bảo đảm huấn luyện bắt buộc về an toàn, vệ sinh lao động đúng đối tượng, đúng hạn, có hồ sơ.","Đánh giá hiệu quả theo Kirkpatrick, tính ROI và báo cáo ban giám đốc."],en:["Analyze training needs at organization, job and individual levels with department heads.","Plan the annual training budget and competency paths for each job family.","Run internal programs and select and supervise external training providers.","Ensure mandatory occupational safety and health training reaches the right people on time with records.","Evaluate impact with Kirkpatrick, compute ROI and report to the board."]},competencies:[{name:{vi:"Phân tích nhu cầu & năng lực",en:"Needs & competency analysis"},desc:{vi:"Xác định khoảng cách năng lực và phân biệt vấn đề cần đào tạo với vấn đề quy trình, công cụ.",en:"Identify competency gaps and separate training needs from process or tooling problems."}},{name:{vi:"Thiết kế chương trình học tập",en:"Learning program design"},desc:{vi:"Kết hợp lớp học, học trực tuyến, kèm cặp và học qua công việc theo mô hình 70-20-10.",en:"Blend classroom, online, coaching and on-the-job learning following the 70-20-10 model."}},{name:{vi:"Đánh giá hiệu quả & ROI",en:"Impact evaluation & ROI"},desc:{vi:"Chọn đúng cấp độ đo, tách tác động đào tạo, tính chi phí đầy đủ và ROI.",en:"Pick the right measurement level, isolate training effects, load full costs and compute ROI."}},{name:{vi:"Quản lý ngân sách & nhà cung cấp",en:"Budget & vendor management"},desc:{vi:"Lập ngân sách, đánh giá nhà cung cấp và kiểm soát chất lượng hợp đồng đào tạo.",en:"Build budgets, assess vendors and control training contract quality."}},{name:{vi:"Tuân thủ & liêm chính",en:"Compliance & integrity"},desc:{vi:"Bảo đảm huấn luyện bắt buộc thật, hồ sơ trung thực và từ chối quà tặng, hồ sơ khống.",en:"Ensure real mandatory training, honest records and refuse gifts or fake paperwork."}}],knowledge:{vi:["Mô hình ADDIE và phân tích nhu cầu đào tạo ba cấp: tổ chức, công việc, cá nhân.","Mô hình đánh giá Kirkpatrick 4 cấp và cấp 5 ROI của Phillips: ROI = lợi ích ròng / chi phí x 100; BCR = lợi ích / chi phí.","Mô hình học tập 70-20-10: học qua công việc, qua người khác và qua đào tạo chính thức.","ISO 10015:2019 hướng dẫn quản lý năng lực và phát triển con người.","Luật An toàn, vệ sinh lao động số 84/2015/QH13 và Nghị định 44/2016/NĐ-CP về huấn luyện an toàn, vệ sinh lao động.","Bộ luật Lao động số 45/2019/QH14 về hợp đồng đào tạo nghề giữa doanh nghiệp và người lao động."],en:["The ADDIE model and three-level training needs analysis: organization, job and individual.","Kirkpatrick's four levels and Phillips' level 5 ROI: ROI = net benefits / costs x 100; BCR = benefits / costs.","The 70-20-10 learning model: learning on the job, from others and through formal training.","ISO 10015:2019 guidelines for competence management and people development.","Occupational Safety and Health Law No. 84/2015/QH13 and Decree 44/2016/ND-CP on safety and health training.","Labor Code No. 45/2019/QH14 on vocational training contracts between employers and employees."]},tools:["Hệ thống quản lý học tập (LMS)","Ma trận năng lực theo vị trí","Phần mềm khảo sát và đánh giá 360 độ","Bảng điều khiển phân tích học tập","Công cụ lập ngân sách đào tạo","Nền tảng lớp học trực tuyến"],kpis:{vi:["Tỷ lệ hoàn thành huấn luyện bắt buộc đúng hạn (mục tiêu 100%).","Tỷ lệ áp dụng hành vi mới khi quan sát tại nơi làm việc.","ROI và chi phí đào tạo trên mỗi nhân viên so với ngân sách.","Mức thăng tiến nội bộ từ nguồn nhân sự đã qua lộ trình phát triển."],en:["On-time completion of mandatory training (target 100%).","Rate of new behaviors observed on the job.","ROI and training cost per employee versus budget.","Internal promotion rate from employees in development paths."]},day:[{time:"08:00",vi:"Xem bảng điều khiển LMS, danh sách huấn luyện bắt buộc sắp hết hạn chứng nhận.",en:"Check the LMS dashboard and mandatory training certificates nearing expiry."},{time:"09:30",vi:"Họp trưởng bộ phận sản xuất phân tích khoảng cách năng lực tổ trưởng.",en:"Meet production heads to analyze team leader competency gaps."},{time:"11:00",vi:"Đánh giá hồ sơ năng lực và báo giá của nhà cung cấp đào tạo bên ngoài.",en:"Review external training providers' credentials and quotes."},{time:"14:00",vi:"Dự giờ lớp nội bộ, quan sát áp dụng tại xưởng và thu thập dữ liệu cấp độ 3.",en:"Observe an internal class and shop-floor application and collect level 3 data."},{time:"16:30",vi:"Tính ROI chương trình, cập nhật ngân sách và báo cáo Giám đốc Nhân sự.",en:"Compute program ROI, update the budget and report to the HR Director."}],mistakes:{vi:["Gọi bài kiểm tra cuối khóa là đánh giá hành vi, trong khi nó chỉ đo cấp độ học tập.","Báo cáo ROI bằng lợi ích chia chi phí (BCR) hoặc bỏ sót chi phí thời gian học viên.","Chấp nhận hồ sơ huấn luyện an toàn khống để đối phó thanh tra, đặt người lao động vào rủi ro."],en:["Calling an end-of-course test a behavior evaluation when it only measures learning.","Reporting ROI as benefits over costs (BCR) or leaving out participant time costs.","Accepting fake safety training records to pass an inspection, putting workers at risk."]},career:[{vi:"Chuyên viên đào tạo",en:"Training specialist"},{vi:"Trưởng nhóm phát triển năng lực",en:"Learning & development lead"},{vi:"Quản lý đào tạo doanh nghiệp",en:"Corporate training manager"},{vi:"Giám đốc học tập & phát triển nhân tài",en:"Head of learning & talent development"}],glossary:[{term:"TNA",vi:"Phân tích nhu cầu đào tạo: xác định khoảng cách giữa năng lực hiện có và năng lực yêu cầu.",en:"Training needs analysis identifying the gap between current and required competence."},{term:"ROI",vi:"Tỷ suất hoàn vốn đào tạo: lợi ích ròng chia tổng chi phí đầy đủ, nhân 100.",en:"Training return on investment: net benefits divided by fully loaded costs, times 100."},{term:"BCR",vi:"Tỷ số lợi ích trên chi phí: lợi ích tiền tệ chia tổng chi phí.",en:"Benefit-cost ratio: monetary benefits divided by total costs."},{term:"70-20-10",vi:"Mô hình cho rằng phần lớn học tập diễn ra qua công việc, tiếp theo là qua người khác và đào tạo chính thức.",en:"A model holding that most learning happens on the job, then through others and formal training."},{term:"Competency matrix",vi:"Ma trận năng lực mô tả năng lực và mức yêu cầu cho từng vị trí.",en:"A matrix describing competencies and required levels for each role."}],quiz:[{q:{vi:"Chương trình có tổng chi phí 200 triệu VND và lợi ích tiền tệ 290 triệu VND. ROI là bao nhiêu?",en:"A program costs 200 million VND in total with 290 million VND of monetary benefits. What is the ROI?"},options:{vi:["145%","45%","90%","69%"],en:["145%","45%","90%","69%"]},answer:1,explain:{vi:"ROI = (290 - 200) / 200 x 100 = 45%; con số 145% là BCR x 100.",en:"ROI = (290 - 200) / 200 x 100 = 45%; 145% is the BCR times 100."}},{q:{vi:"Bài kiểm tra kiến thức ngay cuối khóa học đo cấp độ nào trong mô hình Kirkpatrick?",en:"A knowledge test at the end of a course measures which Kirkpatrick level?"},options:{vi:["Cấp 1 - Phản ứng","Cấp 3 - Hành vi","Cấp 2 - Học tập","Cấp 4 - Kết quả"],en:["Level 1 - Reaction","Level 3 - Behavior","Level 2 - Learning","Level 4 - Results"]},answer:2,explain:{vi:"Cấp 2 đo mức tiếp thu kiến thức, kỹ năng ngay sau đào tạo.",en:"Level 2 measures knowledge and skill gained right after training."}},{q:{vi:"Theo mô hình 70-20-10, phần lớn nhất của học tập đến từ đâu?",en:"In the 70-20-10 model, where does the largest share of learning come from?"},options:{vi:["Khóa học chính thức","Sách và tài liệu","Kèm cặp từ người khác","Trải nghiệm và thử thách trong công việc"],en:["Formal courses","Books and materials","Coaching from others","Experience and challenges on the job"]},answer:3,explain:{vi:"Khoảng 70% học qua công việc, 20% qua người khác và 10% qua đào tạo chính thức.",en:"About 70% comes from the job, 20% from others and 10% from formal training."}},{q:{vi:"Nhà thầu đề nghị cấp chứng nhận huấn luyện an toàn cho công nhân chưa học, kèm quà cảm ơn. Bạn làm gì?",en:"A contractor offers safety training certificates for workers who did not attend, with a thank-you gift. What do you do?"},options:{vi:["Từ chối, báo cáo, tổ chức huấn luyện bù thật và báo cáo trung thực với thanh tra","Nhận vì kịp thanh tra","Nhận chứng nhận nhưng trả lại quà","Chờ thanh tra xong mới quyết định"],en:["Refuse, escalate, run a real make-up course and report honestly to inspectors","Accept to pass the inspection","Accept the certificates but return the gift","Decide after the inspection"]},answer:0,explain:{vi:"Hồ sơ khống vi phạm pháp luật an toàn lao động và đặt người lao động vào nguy hiểm; quà tặng kèm là dấu hiệu hối lộ.",en:"Fake records breach occupational safety law and endanger workers; the gift is a bribery red flag."}}],tools_en:["Learning management system (LMS)","Role-based competency matrix","Survey and 360-degree feedback software","Learning analytics dashboard","Training budget planning tool","Virtual classroom platform"]}},"KK-874":{scenario:{company:"Trường Mầm non Hoa Sen Xanh",supervisor:{name:"Trần Thị Mai Anh",role:{vi:"Phó Hiệu trưởng phụ trách bán trú",en:"Vice Principal for Day Care & Nutrition"}},ref_code:"MN-0417",title:{vi:"Bữa ăn an toàn. Hồ sơ chính xác. Minh bạch với phụ huynh.",en:"Safe meals. Accurate records. Honest with parents."},brief:{vi:"Bạn là giáo viên chủ nhiệm lớp Mẫu giáo 4-5 tuổi. Bé mã MN-0417 có giấy xác nhận của bác sĩ về dị ứng đạm sữa bò. Tháng 10 bé nghỉ 5 ngày: 3 ngày phụ huynh báo nghỉ trước 8:00, 2 ngày không báo. Tiền ăn mô phỏng 32000 đồng/ngày. Đối chiếu phiếu theo dõi nháp với hồ sơ đã duyệt, sửa mã thực đơn và số tiền ăn hoàn trả, rồi lập báo cáo có căn cứ. Đây là tình huống đào tạo.",en:"You are the homeroom teacher of a 4-5 year-old kindergarten class. Child MN-0417 has a doctor's certificate confirming cow's milk protein allergy. In October the child missed 5 days: parents notified 3 absences before 8:00 and 2 without notice. The training meal fee is 32000 VND per day. Compare the draft care record with the approved file, correct the menu code and the meal refund, then write an evidence-based report. This is a training scenario."},reference_title:{vi:"Hồ sơ sức khỏe & bảng chấm ăn đã duyệt · MN-0417",en:"Approved health file & meal attendance sheet · MN-0417"},fields:[{id:"MENU_CODE",label:{vi:"Mã thực đơn bán trú",en:"Day-care menu code"},initial:"MENU-STD",expected:"MENU-DF",choices:["MENU-STD","MENU-DF","MENU-GF"],reference:"Phiếu sức khỏe & dị ứng",hint:{vi:"Giấy bác sĩ xác nhận dị ứng đạm sữa bò: trẻ dùng thực đơn loại bỏ sữa và chế phẩm từ sữa (DF), không phải thực đơn không gluten.",en:"The doctor confirms cow's milk protein allergy: the child needs the dairy-free menu (DF), not the gluten-free one."}},{id:"REFUND_VND",label:{vi:"Tiền ăn hoàn trả tháng 10 (đồng)",en:"October meal refund (VND)"},initial:"160000",expected:"96000",reference:"Bảng chấm ăn tháng 10",ref_value:{vi:"Nghỉ 5 ngày: 3 ngày báo trước 8:00, 2 ngày không báo; tiền ăn 32000 đồng/ngày (mô phỏng)",en:"5 absences: 3 notified before 8:00, 2 without notice; meal fee 32000 VND/day (training)"},hint:{vi:"Chỉ ngày nghỉ được báo trước giờ bếp chốt suất ăn mới được hoàn tiền.",en:"Only absences notified before the kitchen's meal cut-off are refunded."}}],sop32:{vi:"Bếp chốt suất ăn lúc 8:00 hằng ngày. Chỉ hoàn tiền ăn cho ngày nghỉ được phụ huynh báo trước 8:00; tiền hoàn trả = số ngày nghỉ có báo trước x tiền ăn một ngày (số liệu mô phỏng).",en:"The kitchen closes meal orders at 8:00 daily. Only absences notified before 8:00 are refunded; refund = notified absence days x daily meal fee (training figure)."},context:{label:"SỔ THEO DÕI TRẺ / MN-0417",metrics:[{label:{vi:"Sĩ số lớp",en:"Class size"},value:"28"},{label:{vi:"Ngày nghỉ tháng 10",en:"October absences"},value:"5"},{label:{vi:"Tiền ăn mô phỏng/ngày",en:"Training meal fee/day"},value:"32,000 VND"}]},crisis:{vi:"Bếp báo hết sữa thay thế cho bé MN-0417. Một đồng nghiệp nhắn: “Cho bé uống sữa thường một bữa thôi, ít thì không sao, đừng báo phụ huynh kẻo họ làm to chuyện.”",en:"The kitchen has run out of the substitute milk for child MN-0417. A colleague texts: “Just give regular milk for one meal, a little won't hurt, and don't tell the parents or they will make a fuss.”"},options:{safe:{vi:"Không cho trẻ dùng sữa bò, yêu cầu bếp thay món an toàn theo thực đơn DF, báo Phó Hiệu trưởng, thông báo trung thực cho phụ huynh và ghi sổ theo dõi.",en:"Give no cow's milk, ask the kitchen for a safe DF substitute, inform the Vice Principal, tell the parents honestly and log it in the record."},shortcut:{vi:"Cho bé uống ít sữa thường cho đủ bữa và không ghi vào sổ theo dõi.",en:"Give a little regular milk to complete the meal and leave it out of the record."},wait:{vi:"Để bé bỏ bữa phụ, chờ bếp tự xử lý và không báo cho ai.",en:"Let the child skip the snack, wait for the kitchen to sort it out and tell no one."}},questions:{vi:["Vì sao bé MN-0417 phải dùng thực đơn MENU-DF? Căn cứ nào trong hồ sơ sức khỏe chứng minh điều đó?","Giải thích cách tính tiền ăn hoàn trả và cách bạn trao đổi với phụ huynh khi phát hiện sai lệch."],en:["Why must child MN-0417 be on MENU-DF? Which evidence in the health file supports it?","Explain how you calculated the meal refund and how you would talk to the parents about the discrepancy."]},hints:{vi:["Đặt phiếu theo dõi nháp cạnh giấy xác nhận dị ứng và đánh dấu dòng mã thực đơn đang sai.","Tách ngày nghỉ có báo trước 8:00 và ngày không báo trước khi nhân đơn giá theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi sự cố liên quan đến dị ứng phải được báo cáo và thông báo cho phụ huynh."],en:["Place the draft record next to the allergy certificate and flag the wrong menu code line.","Separate absences notified before 8:00 from unnotified ones before applying the rate in SOP 3.2.","Re-read SOP 4.2: every allergy-related incident must be reported and shared with the parents."]}},learning:{summary:{vi:"Giáo viên mầm non chăm sóc, nuôi dưỡng và giáo dục trẻ từ nhà trẻ đến mẫu giáo theo Chương trình giáo dục mầm non: tổ chức hoạt động học qua chơi, bảo đảm an toàn, dinh dưỡng, vệ sinh và theo dõi sự phát triển của từng trẻ. Nghề đòi hỏi tình yêu trẻ, hiểu biết tâm lý phát triển, kỹ năng sơ cứu, khả năng quan sát và phối hợp chặt chẽ, trung thực với gia đình.",en:"An early childhood educator cares for, nurtures and teaches children from nursery to kindergarten age under the national early childhood curriculum: organizing learning through play, ensuring safety, nutrition and hygiene, and tracking each child's development. The role requires genuine care for children, child development knowledge, first aid skills, careful observation and close, honest partnership with families."},responsibilities:{vi:["Lập kế hoạch giáo dục năm, tháng, tuần theo chủ đề và mục tiêu phát triển của độ tuổi.","Tổ chức hoạt động học qua chơi, góc chơi, hoạt động ngoài trời và chế độ sinh hoạt một ngày.","Chăm sóc bữa ăn, giấc ngủ, vệ sinh; quản lý trẻ dị ứng, bệnh mạn tính theo hồ sơ sức khỏe.","Cân đo, theo dõi biểu đồ tăng trưởng và đánh giá sự phát triển của trẻ định kỳ.","Trao đổi với phụ huynh hằng ngày, ghi sổ theo dõi và báo cáo sự cố kịp thời."],en:["Prepare yearly, monthly and weekly education plans by theme and age-group development goals.","Run learning through play, activity corners, outdoor play and the daily routine.","Manage meals, naps and hygiene; handle allergies and chronic conditions per the health file.","Weigh and measure children, track growth charts and assess development periodically.","Talk with parents daily, keep the care record and report incidents promptly."]},competencies:[{name:{vi:"Tổ chức học qua chơi",en:"Play-based learning design"},desc:{vi:"Thiết kế hoạt động phù hợp độ tuổi, lấy trẻ làm trung tâm, kích thích tò mò, ngôn ngữ và vận động.",en:"Design age-appropriate, child-centered activities that build curiosity, language and motor skills."}},{name:{vi:"Chăm sóc & an toàn",en:"Care & safety"},desc:{vi:"Phòng tránh tai nạn thương tích, sơ cứu ban đầu, quản lý dị ứng và giữ vệ sinh an toàn thực phẩm.",en:"Prevent injuries, give first aid, manage allergies and keep food hygiene safe."}},{name:{vi:"Quan sát & đánh giá phát triển",en:"Observation & developmental assessment"},desc:{vi:"Ghi chép quan sát, đối chiếu chỉ số phát triển và phát hiện sớm trẻ cần hỗ trợ can thiệp.",en:"Record observations, compare with development indicators and spot children needing early support."}},{name:{vi:"Hợp tác với gia đình",en:"Family partnership"},desc:{vi:"Trao đổi trung thực, tôn trọng, kịp thời với phụ huynh về tiến bộ và sự cố của trẻ.",en:"Communicate honestly, respectfully and promptly with parents about progress and incidents."}},{name:{vi:"Đạo đức nhà giáo",en:"Professional ethics"},desc:{vi:"Tôn trọng quyền trẻ em, không dùng hình phạt, không che giấu sự cố và bảo mật thông tin gia đình.",en:"Respect children's rights, never use punishment, never hide incidents and protect family information."}}],knowledge:{vi:["Luật Giáo dục số 43/2019/QH14 và Luật Trẻ em số 102/2016/QH13.","Chương trình giáo dục mầm non ban hành kèm Thông tư 17/2009/TT-BGDĐT, đã được sửa đổi, bổ sung (Thông tư 51/2020/TT-BGDĐT).","Điều lệ trường mầm non (Thông tư 52/2020/TT-BGDĐT): tổ chức nhóm, lớp và số trẻ tối đa theo độ tuổi.","Chuẩn nghề nghiệp giáo viên mầm non (Thông tư 26/2018/TT-BGDĐT).","Chuẩn tăng trưởng trẻ em của WHO và nguyên tắc dinh dưỡng, an toàn thực phẩm trong bếp ăn tập thể.","Sơ cứu ban đầu, phòng chống tai nạn thương tích và xử trí phản ứng dị ứng ở trẻ nhỏ."],en:["Education Law No. 43/2019/QH14 and Law on Children No. 102/2016/QH13.","The early childhood education curriculum issued with Circular 17/2009/TT-BGDDT, as amended (Circular 51/2020/TT-BGDDT).","Preschool Charter (Circular 52/2020/TT-BGDDT): group and class organization and maximum class sizes by age.","Professional standards for preschool teachers (Circular 26/2018/TT-BGDDT).","WHO child growth standards and nutrition and food safety principles for school kitchens.","First aid, injury prevention and management of allergic reactions in young children."]},tools:["Phần mềm quản lý trường mầm non","Sổ liên lạc điện tử với phụ huynh","Biểu đồ tăng trưởng chuẩn WHO","Bộ học liệu góc chơi (STEAM, Montessori)","Cân và thước đo chiều cao trẻ em","Túi sơ cứu lớp học"],kpis:{vi:["Số sự cố an toàn, dị ứng trong lớp (mục tiêu bằng 0).","Tỷ lệ trẻ được cân đo đủ kỳ và nằm trong kênh tăng trưởng bình thường.","Tỷ lệ trẻ đạt mục tiêu phát triển cuối độ tuổi.","Mức độ hài lòng của phụ huynh qua khảo sát học kỳ."],en:["Safety and allergy incidents in the class (target zero).","Share of children measured on schedule and within the normal growth channel.","Share of children meeting end-of-age development goals.","Parent satisfaction in the semester survey."]},day:[{time:"07:00",vi:"Đón trẻ, quan sát sức khỏe buổi sáng, nhận thuốc kèm phiếu gửi thuốc có chữ ký phụ huynh.",en:"Welcome children, do the morning health check and receive medicines with a signed parent request form."},{time:"08:00",vi:"Chốt sĩ số, báo suất ăn cho bếp và ghi rõ trẻ cần thực đơn đặc biệt.",en:"Confirm attendance, send meal counts to the kitchen and flag special-diet children."},{time:"09:00",vi:"Tổ chức hoạt động học theo chủ đề, chơi ở các góc và hoạt động ngoài trời.",en:"Run themed learning activities, corner play and outdoor time."},{time:"11:00",vi:"Tổ chức bữa trưa, kiểm tra lại suất ăn đặc biệt rồi cho trẻ ngủ trưa.",en:"Serve lunch, double-check special-diet meals, then supervise nap time."},{time:"16:30",vi:"Trả trẻ, trao đổi với phụ huynh và hoàn thiện sổ theo dõi trong ngày.",en:"Hand children back to parents, share updates and complete the day's care record."}],mistakes:{vi:["Không đối chiếu danh sách dị ứng khi chia suất ăn, để trẻ dị ứng ăn nhầm món.","Hoàn tiền ăn cho mọi ngày nghỉ mà không xét giờ báo nghỉ theo quy định chốt suất ăn.","Che giấu va chạm, trầy xước của trẻ thay vì ghi sổ sự cố và báo phụ huynh."],en:["Not checking the allergy list when serving meals, so an allergic child gets the wrong dish.","Refunding every absence without checking the notice time against the meal cut-off rule.","Hiding a child's bump or scrape instead of logging the incident and informing parents."]},career:[{vi:"Giáo viên mầm non tập sự",en:"Trainee early childhood teacher"},{vi:"Giáo viên mầm non chủ nhiệm lớp",en:"Homeroom early childhood teacher"},{vi:"Tổ trưởng chuyên môn khối mẫu giáo",en:"Kindergarten curriculum team leader"},{vi:"Phó Hiệu trưởng, Hiệu trưởng trường mầm non",en:"Preschool Vice Principal, Principal"}],glossary:[{term:"Play-based learning",vi:"Học qua chơi: trẻ khám phá, trải nghiệm và hình thành kỹ năng thông qua hoạt động chơi có mục đích.",en:"An approach where children explore and build skills through purposeful play."},{term:"Daily routine",vi:"Chế độ sinh hoạt: khung thời gian hợp lý cho đón trẻ, học, chơi, ăn, ngủ, vệ sinh trong ngày.",en:"The structured daily schedule of arrival, learning, play, meals, naps and hygiene."},{term:"Growth chart",vi:"Biểu đồ tăng trưởng: cân nặng, chiều cao theo tuổi dựa trên chuẩn WHO để phát hiện suy dinh dưỡng, thừa cân.",en:"Weight and height-for-age charts based on WHO standards to detect undernutrition or overweight."},{term:"CMPA",vi:"Dị ứng đạm sữa bò ở trẻ nhỏ; phải loại bỏ sữa bò và chế phẩm khỏi khẩu phần theo chỉ định của bác sĩ.",en:"Cow's milk protein allergy; milk and dairy products must be removed from the diet as prescribed."},{term:"Meal count",vi:"Báo suất ăn: số suất giáo viên chốt với bếp mỗi sáng theo sĩ số thực tế và chế độ ăn đặc biệt.",en:"The number of meals the teacher confirms to the kitchen each morning from attendance and special diets."}],quiz:[{q:{vi:"Theo Điều lệ trường mầm non, lớp mẫu giáo 4-5 tuổi có tối đa bao nhiêu trẻ?",en:"Under the Preschool Charter, what is the maximum size of a 4-5 year-old class?"},options:{vi:["25 trẻ","30 trẻ","35 trẻ","40 trẻ"],en:["25 children","30 children","35 children","40 children"]},answer:1,explain:{vi:"Điều lệ quy định lớp 3-4 tuổi tối đa 25 trẻ, 4-5 tuổi tối đa 30 trẻ, 5-6 tuổi tối đa 35 trẻ.",en:"The Charter sets a maximum of 25 children for ages 3-4, 30 for ages 4-5 and 35 for ages 5-6."}},{q:{vi:"Bé nghỉ 4 ngày: 1 ngày báo trước 8:00, 3 ngày không báo; tiền ăn mô phỏng 30000 đồng/ngày, bếp chốt suất lúc 8:00. Tiền hoàn trả là bao nhiêu?",en:"A child misses 4 days: 1 notified before 8:00, 3 without notice; training meal fee 30000 VND/day, kitchen cut-off 8:00. What is the refund?"},options:{vi:["120000 đồng","90000 đồng","30000 đồng","0 đồng"],en:["120000 VND","90000 VND","30000 VND","0 VND"]},answer:2,explain:{vi:"Chỉ 1 ngày được báo trước giờ chốt suất: 1 x 30000 = 30000 đồng.",en:"Only 1 day was notified before the cut-off: 1 x 30000 = 30000 VND."}},{q:{vi:"Bếp hết sữa thay thế cho trẻ dị ứng đạm sữa bò, đồng nghiệp bảo cho uống sữa thường một bữa. Bạn làm gì?",en:"The kitchen has no substitute milk for a child with cow's milk allergy and a colleague suggests regular milk once. What do you do?"},options:{vi:["Cho uống ít một bữa","Để trẻ nhịn và không báo ai","Hỏi ý kiến các trẻ khác","Không cho dùng, đổi món an toàn, báo cấp trên và phụ huynh"],en:["Give a little just once","Let the child go without and tell no one","Ask the other children","Refuse, serve a safe substitute, inform the manager and parents"]},answer:3,explain:{vi:"Dị ứng có thể gây phản ứng nặng dù lượng nhỏ; an toàn của trẻ và sự minh bạch với gia đình là ưu tiên.",en:"Allergies can cause severe reactions even in small amounts; child safety and transparency with families come first."}},{q:{vi:"Phụ huynh nhờ cho trẻ uống thuốc ở trường. Giáo viên cần gì trước khi cho uống?",en:"A parent asks you to give a child medicine at school. What do you need first?"},options:{vi:["Phiếu gửi thuốc có chữ ký phụ huynh ghi rõ tên thuốc, liều, giờ uống","Chỉ cần lời dặn miệng","Tự điều chỉnh liều theo cân nặng của trẻ","Không cần gì nếu là thuốc bổ"],en:["A signed request stating the medicine, dose and time","A verbal instruction is enough","Adjust the dose yourself by the child's weight","Nothing if it is a vitamin"]},answer:0,explain:{vi:"Phải có yêu cầu bằng văn bản của phụ huynh và ghi sổ cho uống thuốc để bảo đảm đúng thuốc, đúng liều, đúng giờ.",en:"A written parent request and a medication log ensure the right medicine, dose and time."}}],tools_en:["Preschool management software","Electronic parent communication log","WHO standard growth charts","Play corner learning kits (STEAM, Montessori)","Child scales and height measuring boards","Classroom first aid kit"]}},"KK-875":{scenario:{company:"Trường Đại học Công nghệ Bắc Hà",supervisor:{name:"Lê Minh Khoa",role:{vi:"Trưởng phòng Công tác Sinh viên",en:"Head of Student Affairs"}},ref_code:"SV-2381",title:{vi:"Đúng quy chế. Đúng học bổng. Công bằng cho người học.",en:"Right rules. Right scholarship. Fair to every student."},brief:{vi:"Bạn rà soát hồ sơ xét học bổng khuyến khích học tập học kỳ I của sinh viên mã SV-2381: điểm trung bình học kỳ 3.45/4, điểm rèn luyện 79/100. Mức học bổng mô phỏng mỗi tháng: HB-A 2000000, HB-B 1700000, HB-C 1450000 đồng; học kỳ tính 5 tháng. Đối chiếu bản nháp với quy chế đã duyệt, sửa loại học bổng và tổng tiền học kỳ, rồi lập báo cáo có căn cứ.",en:"You are reviewing the semester 1 merit scholarship file of student SV-2381: semester GPA 3.45/4, conduct score 79/100. Training monthly rates: HB-A 2000000, HB-B 1700000, HB-C 1450000 VND; a semester counts as 5 months. Compare the draft with the approved regulation, correct the scholarship tier and the semester total, then write an evidence-based report."},reference_title:{vi:"Quy chế học bổng & biên bản hội đồng đã duyệt · SV-2381",en:"Approved scholarship regulation & committee minutes · SV-2381"},fields:[{id:"SCH_TIER",label:{vi:"Loại học bổng",en:"Scholarship tier"},initial:"HB-B",expected:"HB-C",choices:["HB-A","HB-B","HB-C"],reference:"Quy chế học bổng mục 2",hint:{vi:"Loại học bổng phải thỏa đồng thời điều kiện học tập và rèn luyện; 79 điểm rèn luyện chưa đạt mức tốt.",en:"The tier must meet both academic and conduct conditions; a conduct score of 79 is below the good band."}},{id:"SCH_TOTAL",label:{vi:"Tổng học bổng học kỳ (đồng)",en:"Semester scholarship total (VND)"},initial:"8500000",expected:"7250000",reference:"Bảng mức học bổng học kỳ I",ref_value:{vi:"Mức tháng: HB-A 2000000, HB-B 1700000, HB-C 1450000 đồng; học kỳ 5 tháng (mô phỏng)",en:"Monthly: HB-A 2000000, HB-B 1700000, HB-C 1450000 VND; 5-month semester (training)"},hint:{vi:"Xác định đúng loại học bổng trước, rồi mới nhân mức tháng với số tháng của học kỳ.",en:"Fix the tier first, then multiply its monthly rate by the semester months."}}],sop32:{vi:"HB-A: học tập 3.6-4.0 và rèn luyện 90-100; HB-B: học tập từ 3.2 và rèn luyện từ 80; HB-C: học tập từ 2.5 và rèn luyện từ 65. Phải đạt cả hai điều kiện; tổng học kỳ = mức tháng x 5 tháng (mô phỏng).",en:"HB-A: GPA 3.6-4.0 and conduct 90-100; HB-B: GPA from 3.2 and conduct from 80; HB-C: GPA from 2.5 and conduct from 65. Both conditions must be met; semester total = monthly rate x 5 months (training)."},context:{label:"HỒ SƠ XÉT HỌC BỔNG / SV-2381",metrics:[{label:{vi:"Điểm TB học kỳ",en:"Semester GPA"},value:"3.45 / 4"},{label:{vi:"Điểm rèn luyện",en:"Conduct score"},value:"79 / 100"},{label:{vi:"Số tháng học kỳ",en:"Semester months"},value:"5"}]},crisis:{vi:"Cố vấn học tập của lớp nhắn: “Cộng thêm 1 điểm rèn luyện cho em ấy lên 80 đi, gia đình khó khăn, chênh có 1 điểm, hội đồng không soát lại đâu.”",en:"The class academic advisor texts: “Just add 1 conduct point so the student reaches 80. The family is struggling, it is only 1 point and the committee will not recheck.”"},options:{safe:{vi:"Giữ đúng 79 điểm theo biên bản đã duyệt, báo Trưởng phòng; hướng dẫn sinh viên phúc khảo nếu có minh chứng và giới thiệu chính sách hỗ trợ sinh viên khó khăn.",en:"Keep the approved 79 points and inform the Head of Student Affairs; guide the student to appeal with evidence and refer them to hardship support."},shortcut:{vi:"Sửa điểm rèn luyện lên 80 để sinh viên nhận HB-B, coi như giúp đỡ hoàn cảnh khó khăn.",en:"Change the conduct score to 80 so the student gets HB-B, as a favor for a hardship case."},wait:{vi:"Giữ hồ sơ lại, không trả lời cố vấn và chờ hội đồng tự phát hiện sai lệch.",en:"Hold the file, ignore the advisor and wait for the committee to spot the error."}},questions:{vi:["Vì sao sinh viên SV-2381 thuộc loại HB-C chứ không phải HB-B? Dẫn chứng bằng điểm và điều kiện của quy chế.","Trình bày cách tính tổng học bổng học kỳ và cách bạn hỗ trợ sinh viên khó khăn mà vẫn bảo đảm công bằng."],en:["Why is student SV-2381 in tier HB-C rather than HB-B? Cite the scores and the regulation conditions.","Explain how you calculated the semester total and how you would support a struggling student while staying fair."]},hints:{vi:["Đặt điểm học tập và điểm rèn luyện cạnh bảng điều kiện từng loại, đánh dấu điều kiện chưa đạt.","Lấy đúng mức tháng của loại học bổng đã sửa rồi nhân số tháng theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không sửa điểm đã được hội đồng phê duyệt; mọi đề nghị phải đi qua phúc khảo."],en:["Put the GPA and conduct score next to each tier's conditions and flag the unmet one.","Take the monthly rate of the corrected tier and multiply by the months in SOP 3.2.","Re-read SOP 4.2: approved scores are never edited; every request goes through the appeal process."]}},learning:{summary:{vi:"Chuyên viên công tác sinh viên và hướng nghiệp đồng hành cùng người học trong suốt quá trình học: đánh giá rèn luyện, xét học bổng và chế độ chính sách, tư vấn học đường, hướng nghiệp, kết nối thực tập và việc làm, khảo sát việc làm sau tốt nghiệp. Nghề đòi hỏi am hiểu quy chế, công bằng, bảo mật thông tin và kỹ năng tư vấn lấy người học làm trung tâm.",en:"A student affairs and career guidance officer supports learners throughout their studies: conduct assessment, scholarships and welfare policies, student counseling, career guidance, internship and job matching, and graduate employment surveys. The role requires solid knowledge of regulations, fairness, data confidentiality and student-centered counseling skills."},responsibilities:{vi:["Tổ chức đánh giá kết quả rèn luyện, xét học bổng, miễn giảm học phí và trợ cấp theo quy chế.","Tư vấn học tập, tâm lý học đường và hướng nghiệp cá nhân, nhóm cho sinh viên.","Kết nối doanh nghiệp, tổ chức ngày hội việc làm và quản lý chương trình thực tập.","Khảo sát tình hình việc làm của sinh viên tốt nghiệp và lập báo cáo phục vụ kiểm định.","Quản lý hồ sơ sinh viên, xử lý vi phạm theo quy trình và bảo mật dữ liệu cá nhân."],en:["Run conduct assessments, scholarships, tuition waivers and allowances under the regulations.","Provide academic, wellbeing and career counseling to individuals and groups.","Build employer links, organize job fairs and manage internship programs.","Survey graduate employment and prepare reports for accreditation.","Manage student records, handle misconduct through due process and protect personal data."]},competencies:[{name:{vi:"Quy chế & chính sách",en:"Regulations & policy"},desc:{vi:"Áp dụng chính xác quy chế đào tạo, rèn luyện, học bổng và chế độ chính sách cho từng trường hợp.",en:"Apply training, conduct, scholarship and welfare regulations accurately to each case."}},{name:{vi:"Tư vấn hướng nghiệp",en:"Career counseling"},desc:{vi:"Dùng công cụ đánh giá sở thích, năng lực để giúp sinh viên tự ra quyết định nghề nghiệp.",en:"Use interest and ability assessments to help students make their own career decisions."}},{name:{vi:"Kết nối doanh nghiệp",en:"Employer engagement"},desc:{vi:"Xây dựng mạng lưới đối tác thực tập, tuyển dụng và đo lường hiệu quả hợp tác.",en:"Build a network of internship and hiring partners and measure partnership results."}},{name:{vi:"Phân tích dữ liệu người học",en:"Student data analysis"},desc:{vi:"Tổng hợp điểm, tỷ lệ việc làm, cảnh báo học vụ để phát hiện sớm sinh viên cần hỗ trợ.",en:"Combine grades, employment rates and academic warnings to identify students needing help early."}},{name:{vi:"Công bằng & bảo mật",en:"Fairness & confidentiality"},desc:{vi:"Xét duyệt khách quan, không thiên vị, không sửa kết quả đã duyệt và bảo vệ dữ liệu cá nhân.",en:"Decide objectively without favoritism, never alter approved results and protect personal data."}}],knowledge:{vi:["Luật Giáo dục đại học số 08/2012/QH13, sửa đổi bởi Luật số 34/2018/QH14.","Quy chế đào tạo trình độ đại học (Thông tư 08/2021/TT-BGDĐT): thang điểm 4 và xếp loại học lực.","Quy chế đánh giá kết quả rèn luyện của người học (Thông tư 16/2015/TT-BGDĐT): thang 100 điểm, 6 mức xếp loại.","Quy chế công tác sinh viên đối với chương trình đào tạo đại học hệ chính quy (Thông tư 10/2016/TT-BGDĐT).","Lý thuyết lựa chọn nghề của Holland (RIASEC) và lý thuyết phát triển nghề nghiệp suốt đời của Super.","Nghị định 13/2023/NĐ-CP và pháp luật hiện hành về bảo vệ dữ liệu cá nhân của người học."],en:["Higher Education Law No. 08/2012/QH13, amended by Law No. 34/2018/QH14.","Undergraduate training regulation (Circular 08/2021/TT-BGDDT): 4-point scale and academic standing.","Regulation on learner conduct assessment (Circular 16/2015/TT-BGDDT): 100-point scale with 6 bands.","Regulation on student affairs for full-time undergraduate programs (Circular 10/2016/TT-BGDDT).","Holland's career choice theory (RIASEC) and Super's life-span career development theory.","Decree 13/2023/ND-CP and current law on protecting learners' personal data."]},tools:["Phần mềm quản lý sinh viên","Trắc nghiệm sở thích nghề nghiệp RIASEC","Cổng việc làm và thực tập của trường","Biểu mẫu khảo sát trực tuyến","Microsoft Excel","Hệ thống quản lý quan hệ doanh nghiệp (CRM)"],kpis:{vi:["Tỷ lệ hồ sơ học bổng, chính sách xét đúng quy chế, không phải điều chỉnh sau công bố.","Tỷ lệ sinh viên có việc làm trong 12 tháng sau tốt nghiệp.","Số doanh nghiệp đối tác và vị trí thực tập được kết nối mỗi năm.","Mức độ hài lòng của sinh viên với dịch vụ tư vấn."],en:["Share of scholarship and welfare decisions correct first time with no post-publication changes.","Share of graduates employed within 12 months.","Partner employers and internship places secured each year.","Student satisfaction with counseling services."]},day:[{time:"08:00",vi:"Tiếp nhận đơn, giải đáp thắc mắc về học bổng và chế độ chính sách tại bộ phận một cửa.",en:"Receive applications and answer scholarship and welfare questions at the service desk."},{time:"09:30",vi:"Tổng hợp điểm học tập, điểm rèn luyện và lập danh sách dự kiến xét học bổng.",en:"Compile GPAs and conduct scores and draft the scholarship shortlist."},{time:"13:30",vi:"Tư vấn hướng nghiệp cá nhân, phân tích kết quả trắc nghiệm sở thích nghề nghiệp.",en:"Hold one-to-one career sessions and interpret interest inventory results."},{time:"15:00",vi:"Làm việc với doanh nghiệp đối tác về chương trình thực tập và ngày hội việc làm.",en:"Meet partner employers about internships and the upcoming job fair."},{time:"16:30",vi:"Cập nhật dữ liệu khảo sát việc làm và lưu hồ sơ theo quy định bảo mật.",en:"Update graduate survey data and file records under confidentiality rules."}],mistakes:{vi:["Xét học bổng chỉ theo điểm học tập, bỏ qua điều kiện điểm rèn luyện.","Chia sẻ danh sách sinh viên kèm số điện thoại cho doanh nghiệp khi chưa có sự đồng ý.","Tư vấn áp đặt theo ngành “hot” thay vì dựa trên sở thích và năng lực của sinh viên."],en:["Awarding scholarships on GPA alone and ignoring the conduct score condition.","Sharing student lists with phone numbers with employers without consent.","Pushing trendy majors instead of building on the student's interests and abilities."]},career:[{vi:"Chuyên viên công tác sinh viên",en:"Student affairs officer"},{vi:"Chuyên viên tư vấn hướng nghiệp & quan hệ doanh nghiệp",en:"Career counselor & employer relations officer"},{vi:"Phó Trưởng phòng Công tác sinh viên",en:"Deputy Head of Student Affairs"},{vi:"Trưởng phòng Công tác sinh viên, Giám đốc Trung tâm Hướng nghiệp",en:"Head of Student Affairs, Director of Career Center"}],glossary:[{term:"Conduct score",vi:"Điểm rèn luyện: kết quả đánh giá ý thức, đạo đức và mức độ tham gia hoạt động của sinh viên theo thang 100.",en:"Assessment of a student's attitude, ethics and participation on a 100-point scale."},{term:"GPA",vi:"Điểm trung bình chung học kỳ hoặc tích lũy, thường theo thang 4 trong đào tạo tín chỉ.",en:"Semester or cumulative grade point average, usually on a 4-point scale in credit-based programs."},{term:"RIASEC",vi:"Mô hình Holland chia sở thích nghề thành 6 nhóm: Kỹ thuật, Nghiên cứu, Nghệ thuật, Xã hội, Quản lý, Nghiệp vụ.",en:"Holland's model of six interest types: Realistic, Investigative, Artistic, Social, Enterprising, Conventional."},{term:"Appeal review",vi:"Phúc khảo: thủ tục người học đề nghị xem xét lại kết quả đánh giá kèm minh chứng.",en:"The procedure for a learner to request a review of an assessment result with evidence."},{term:"Tracer study",vi:"Khảo sát theo dấu sinh viên tốt nghiệp để đo tỷ lệ có việc làm và mức độ phù hợp với ngành học.",en:"A survey that follows graduates to measure employment and fit with their field of study."}],quiz:[{q:{vi:"Theo quy chế đánh giá rèn luyện, sinh viên đạt 79 điểm được xếp loại gì?",en:"Under the conduct assessment regulation, what band is a score of 79?"},options:{vi:["Xuất sắc","Tốt","Khá","Trung bình"],en:["Excellent","Good","Fairly good","Average"]},answer:2,explain:{vi:"Xuất sắc 90-100, tốt 80 đến dưới 90, khá 65 đến dưới 80; vì vậy 79 điểm là loại khá.",en:"Excellent is 90-100, good is 80 to under 90, fairly good is 65 to under 80; so 79 is fairly good."}},{q:{vi:"Sinh viên đạt HB-B với mức mô phỏng 1700000 đồng/tháng, học kỳ 5 tháng. Tổng học bổng học kỳ là bao nhiêu?",en:"A student qualifies for HB-B at a training rate of 1700000 VND/month for a 5-month semester. What is the total?"},options:{vi:["8500000 đồng","1700000 đồng","10200000 đồng","7250000 đồng"],en:["8500000 VND","1700000 VND","10200000 VND","7250000 VND"]},answer:0,explain:{vi:"Tổng học kỳ = mức tháng x số tháng = 1700000 x 5 = 8500000 đồng.",en:"Semester total = monthly rate x months = 1700000 x 5 = 8500000 VND."}},{q:{vi:"Doanh nghiệp đối tác xin danh sách sinh viên năm cuối kèm số điện thoại để mời phỏng vấn. Bạn làm gì?",en:"A partner employer asks for a list of final-year students with phone numbers to invite them to interviews. What do you do?"},options:{vi:["Gửi ngay vì có lợi cho sinh viên","Chỉ gửi cho doanh nghiệp quen biết","Gửi danh sách nhưng xóa bớt cột điểm","Chỉ chia sẻ khi sinh viên đồng ý hoặc đăng tin để sinh viên tự ứng tuyển"],en:["Send it at once as it helps students","Send it only to familiar employers","Send it with the grade column removed","Share only with student consent or post the vacancy for students to apply"]},answer:3,explain:{vi:"Số điện thoại là dữ liệu cá nhân; chỉ chia sẻ khi có sự đồng ý hoặc để sinh viên chủ động ứng tuyển.",en:"Phone numbers are personal data; share only with consent or let students apply themselves."}},{q:{vi:"Mô hình RIASEC của Holland được dùng để làm gì trong hướng nghiệp?",en:"What is Holland's RIASEC model used for in career guidance?"},options:{vi:["Tính điểm rèn luyện","Xác định nhóm sở thích nghề nghiệp để gợi ý ngành, việc làm phù hợp","Xếp loại học bổng","Đo chỉ số IQ"],en:["Calculating conduct scores","Identifying interest types to suggest suitable fields and jobs","Ranking scholarships","Measuring IQ"]},answer:1,explain:{vi:"RIASEC mô tả 6 nhóm sở thích nghề, giúp đối chiếu cá nhân với môi trường nghề nghiệp phù hợp.",en:"RIASEC describes six interest types that help match a person with suitable work environments."}}],tools_en:["Student information system","RIASEC career interest inventory","University jobs and internships portal","Online survey forms","Microsoft Excel","Employer relationship management system (CRM)"]}},"KK-876":{scenario:{company:"Học viện Doanh nghiệp Minh Phát",supervisor:{name:"Hứa Thanh Tùng",role:{vi:"Trưởng phòng Đào tạo số",en:"Head of Digital Learning"}},ref_code:"CRS-4120",title:{vi:"Đúng chuẩn gói. Đúng điểm đạt. Dữ liệu học tập trung thực.",en:"Right package standard. Right pass mark. True learning records."},brief:{vi:"Khóa an toàn lao động bắt buộc CRS-4120 trên LMS không ghi nhận hoàn thành sau 3 ngày. Gói nội dung đóng gói theo SCORM 2004 4th Edition; bài kiểm tra cuối khóa 40 câu, mỗi câu 4 điểm; chính sách yêu cầu đạt từ 85% tổng điểm. Đối chiếu cấu hình nháp với hồ sơ triển khai đã duyệt, dùng terminal chẩn đoán, sửa chuẩn gói nội dung và điểm đạt (nhập theo điểm), rồi lập báo cáo có căn cứ.",en:"Mandatory safety course CRS-4120 on the LMS has recorded no completions after 3 days. The content package is SCORM 2004 4th Edition; the final quiz has 40 questions worth 4 points each; policy requires at least 85% of total points. Compare the draft configuration with the approved deployment file, diagnose in the terminal, fix the package standard and the pass mark (entered in points), then write an evidence-based report."},reference_title:{vi:"Hồ sơ triển khai khóa học đã duyệt · CRS-4120",en:"Approved course deployment file · CRS-4120"},fields:[{id:"PKG_STD",label:{vi:"Chuẩn gói nội dung khi nhập",en:"Package standard on import"},initial:"SCORM-1.2",expected:"SCORM-2004",choices:["SCORM-1.2","SCORM-2004","xAPI"],reference:"Phiếu kiểm tra gói nội dung",hint:{vi:"Đọc schemaversion trong imsmanifest.xml: gói 2004 cần LMS cung cấp đối tượng API_1484_11, không phải API của bản 1.2.",en:"Read schemaversion in imsmanifest.xml: a 2004 package needs the API_1484_11 object, not the 1.2 API."}},{id:"GRADE_PASS",label:{vi:"Điểm đạt bài kiểm tra (điểm)",en:"Quiz grade to pass (points)"},initial:"85",expected:"136",reference:"Cấu hình bài kiểm tra cuối khóa",ref_value:{vi:"40 câu x 4 điểm/câu; chính sách đạt từ 85% tổng điểm",en:"40 questions x 4 points each; policy pass mark 85% of total points"},hint:{vi:"Ô điểm đạt nhận giá trị theo thang điểm của bài kiểm tra, không phải phần trăm.",en:"The grade-to-pass box takes points on the quiz scale, not a percentage."}}],sop32:{vi:"Điểm đạt trên LMS nhập theo điểm: điểm đạt = số câu x điểm mỗi câu x tỷ lệ đạt theo chính sách. Không nhập phần trăm vào ô điểm đạt.",en:"The LMS pass mark is entered in points: grade to pass = questions x points per question x policy pass rate. Never type a percentage into the grade-to-pass box."},context:{label:"LMS ADMIN / CRS-4120",metrics:[{label:{vi:"Học viên ghi danh",en:"Enrolled learners"},value:"1,180"},{label:{vi:"Bản ghi hoàn thành",en:"Completion records"},value:"0"},{label:{vi:"Tỷ lệ đạt theo chính sách",en:"Policy pass rate"},value:"85%"}]},terminal:{system:"lms-admin",settable:["PKG_STD","GRADE_PASS"],commands:[{cmd:"status",out:{vi:"Khóa CRS-4120: 1.180 học viên ghi danh, 0 bản ghi hoàn thành sau 3 ngày; gói đang chạy ở chế độ SCORM 1.2; điểm đạt bài kiểm tra = 85",en:"Course CRS-4120: 1,180 enrolled, 0 completion records after 3 days; package running in SCORM 1.2 mode; quiz grade to pass = 85"}},{cmd:"cat imsmanifest.xml",out:{vi:"Siêu dữ liệu: schema ADL SCORM, schemaversion 2004 4th Edition; ngưỡng đạt imsss:minNormalizedMeasure 0.85",en:"Metadata: schema ADL SCORM, schemaversion 2004 4th Edition; pass threshold imsss:minNormalizedMeasure 0.85"}},{cmd:"tail scorm.log",out:{vi:"[LỖI] Gói nội dung không tìm thấy đối tượng API_1484_11, chỉ thấy API (1.2); cmi.completion_status và cmi.success_status không được lưu",en:"[ERROR] Content cannot find API_1484_11, only API (1.2) is exposed; cmi.completion_status and cmi.success_status are not stored"}},{cmd:"quiz info final",out:{vi:"Bài kiểm tra cuối khóa: 40 câu, mỗi câu 4 điểm; điểm đạt đang đặt 85; học viên được làm tối đa 3 lần",en:"Final quiz: 40 questions, 4 points each; grade to pass currently 85; learners get up to 3 attempts"}},{cmd:"cat policy.txt",out:{vi:"Chính sách đào tạo an toàn bắt buộc: học viên đạt khi đạt từ 85% tổng điểm bài kiểm tra cuối khóa và xem hết 100% nội dung",en:"Mandatory safety training policy: a learner passes with at least 85% of the final quiz total and 100% of content viewed"}}]},crisis:{vi:"Giám đốc Nhân sự nhắn: “Ngày mai thanh tra lao động đến. Đánh dấu hoàn thành hàng loạt cho cả 1.180 người đi, sau này cho học bù cũng được.”",en:"The HR Director texts: “Labor inspectors arrive tomorrow. Bulk-mark all 1,180 people as completed, they can catch up later.”"},options:{safe:{vi:"Từ chối tạo dữ liệu hoàn thành giả, báo Trưởng phòng Đào tạo số; sửa gói và điểm đạt, gia hạn có phê duyệt và nộp báo cáo tiến độ trung thực kèm kế hoạch khắc phục.",en:"Refuse to fake completions and inform the Head of Digital Learning; fix the package and pass mark, extend the deadline with approval and report progress honestly with a remediation plan."},shortcut:{vi:"Chạy lệnh đánh dấu hoàn thành hàng loạt để kịp đoàn thanh tra, sửa lỗi gói sau.",en:"Run a bulk completion update for the inspection and fix the package later."},wait:{vi:"Không phản hồi, giữ nguyên lỗi và chờ nhà cung cấp nội dung tự kiểm tra.",en:"Do not respond, leave the fault and wait for the content vendor to check it."}},questions:{vi:["Vì sao gói CRS-4120 phải nhập theo SCORM-2004? Dòng nhật ký và tệp manifest nào chứng minh nhận định của bạn?","Giải thích cách tính điểm đạt và rủi ro pháp lý nếu đánh dấu hoàn thành khóa an toàn khi người lao động chưa học."],en:["Why must package CRS-4120 be imported as SCORM-2004? Which log line and manifest entry support your conclusion?","Explain how you calculated the pass mark and the legal risk of marking safety training complete when workers have not taken it."]},hints:{vi:["Mở imsmanifest.xml và so schemaversion với chế độ gói đang chạy trên LMS.","Tính tổng điểm bài kiểm tra rồi áp tỷ lệ đạt theo SOP mục 3.2, nhập kết quả theo điểm.","Đọc lại SOP mục 4.2: dữ liệu hoàn thành đào tạo là hồ sơ pháp lý, không được tạo giả dưới bất kỳ áp lực nào."],en:["Open imsmanifest.xml and compare schemaversion with the package mode running on the LMS.","Work out the quiz total, apply the pass rate in SOP 3.2 and enter the result in points.","Re-read SOP 4.2: training completion data is a legal record and must never be faked under any pressure."]}},learning:{summary:{vi:"Chuyên viên quản trị hệ thống học tập trực tuyến vận hành nền tảng LMS: cấu hình khóa học, nhập gói nội dung SCORM, xAPI, quản lý người dùng và phân quyền, ghi danh tự động, báo cáo tiến độ và bảo đảm dữ liệu học tập chính xác, an toàn. Nghề kết hợp kỹ năng quản trị hệ thống, hiểu biết chuẩn e-learning và tư duy thiết kế đào tạo để người học có trải nghiệm thông suốt.",en:"An LMS and e-learning administrator runs the learning platform: configuring courses, importing SCORM and xAPI packages, managing users and roles, automating enrollments, reporting progress and keeping learning data accurate and secure. The role combines system administration, knowledge of e-learning standards and instructional design thinking so learners get a seamless experience."},responsibilities:{vi:["Cài đặt, cấu hình, cập nhật nền tảng LMS, plugin và tích hợp đăng nhập một lần (SSO).","Kiểm thử và nhập gói nội dung SCORM 1.2, SCORM 2004, xAPI; cấu hình điều kiện hoàn thành.","Quản lý người dùng, nhóm, vai trò và quy tắc ghi danh tự động theo dữ liệu nhân sự.","Lập báo cáo tiến độ, tỷ lệ hoàn thành, điểm số cho bộ phận đào tạo và quản lý.","Sao lưu, giám sát hiệu năng, xử lý sự cố và bảo vệ dữ liệu cá nhân người học."],en:["Install, configure and update the LMS, plugins and single sign-on (SSO) integration.","Test and import SCORM 1.2, SCORM 2004 and xAPI packages and set completion rules.","Manage users, groups, roles and automatic enrollment rules from HR data.","Produce progress, completion and grade reports for training teams and managers.","Run backups, monitor performance, resolve incidents and protect learners' personal data."]},competencies:[{name:{vi:"Chuẩn e-learning",en:"E-learning standards"},desc:{vi:"Hiểu SCORM, xAPI, cmi5, LTI để nhập, theo dõi và gỡ lỗi nội dung đúng chuẩn.",en:"Understand SCORM, xAPI, cmi5 and LTI to import, track and debug content correctly."}},{name:{vi:"Quản trị nền tảng",en:"Platform administration"},desc:{vi:"Cấu hình máy chủ, plugin, phân quyền, SSO và kiểm soát thay đổi có môi trường thử.",en:"Configure servers, plugins, roles and SSO with change control and a staging environment."}},{name:{vi:"Cấu hình đánh giá & sổ điểm",en:"Assessment & gradebook setup"},desc:{vi:"Thiết lập ngân hàng câu hỏi, điểm đạt, số lần làm bài và trọng số sổ điểm chính xác.",en:"Set question banks, pass marks, attempts and gradebook weights accurately."}},{name:{vi:"Phân tích dữ liệu học tập",en:"Learning analytics"},desc:{vi:"Truy vấn, trực quan hóa tỷ lệ hoàn thành, điểm số và phát hiện điểm nghẽn của khóa học.",en:"Query and visualize completion and scores and find course bottlenecks."}},{name:{vi:"Toàn vẹn dữ liệu & bảo mật",en:"Data integrity & security"},desc:{vi:"Không sửa kết quả học tập trái quy trình, ghi nhật ký thay đổi và bảo vệ dữ liệu cá nhân.",en:"Never alter learning results outside process, log changes and protect personal data."}}],knowledge:{vi:["Chuẩn ADL SCORM 1.2 và SCORM 2004 (4th Edition): manifest, mô hình dữ liệu cmi và trình tự hóa.","Experience API (xAPI), cmi5 và kho bản ghi học tập LRS.","Chuẩn tích hợp 1EdTech LTI 1.3 và đăng nhập một lần SAML 2.0, OpenID Connect.","Hướng dẫn tiếp cận nội dung web WCAG 2.1 và 2.2 của W3C.","Mô hình thiết kế đào tạo ADDIE và mô hình đánh giá đào tạo 4 cấp độ Kirkpatrick.","Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân và ISO/IEC 27001 về an toàn thông tin."],en:["ADL SCORM 1.2 and SCORM 2004 (4th Edition): manifest, cmi data model and sequencing.","Experience API (xAPI), cmi5 and the Learning Record Store.","1EdTech LTI 1.3 integration and SAML 2.0 or OpenID Connect single sign-on.","W3C Web Content Accessibility Guidelines WCAG 2.1 and 2.2.","The ADDIE instructional design model and Kirkpatrick's four-level evaluation model.","Decree 13/2023/ND-CP on personal data protection and ISO/IEC 27001 information security."]},tools:["Nền tảng LMS (Moodle, Canvas)","Công cụ kiểm thử gói SCORM/xAPI","Kho bản ghi học tập (LRS)","Công cụ soạn bài giảng e-learning","SQL và công cụ báo cáo BI","Công cụ nhà phát triển của trình duyệt"],kpis:{vi:["Thời gian hoạt động của LMS (mục tiêu từ 99,5%).","Tỷ lệ gói nội dung ghi nhận hoàn thành đúng ngay lần triển khai đầu.","Thời gian trung bình xử lý yêu cầu hỗ trợ của học viên.","Tỷ lệ hoàn thành khóa bắt buộc đúng hạn."],en:["LMS uptime (target 99.5% or higher).","Share of packages tracking completion correctly on first deployment.","Average time to resolve learner support tickets.","On-time completion rate of mandatory courses."]},day:[{time:"08:00",vi:"Kiểm tra bảng giám sát LMS, nhật ký lỗi đêm qua và kết quả sao lưu.",en:"Check the LMS dashboard, overnight error logs and backup results."},{time:"09:30",vi:"Kiểm thử gói SCORM mới trên môi trường thử trước khi đưa lên hệ thống chính.",en:"Test a new SCORM package in staging before releasing it to production."},{time:"13:30",vi:"Cấu hình khóa học, sổ điểm, điều kiện hoàn thành và quy tắc ghi danh.",en:"Configure a course, gradebook, completion rules and enrollment rules."},{time:"15:30",vi:"Xử lý phiếu hỗ trợ: không lưu tiến độ, không vào được bài, lỗi cấp chứng chỉ.",en:"Handle tickets: progress not saved, launch failures and certificate errors."},{time:"17:00",vi:"Xuất báo cáo tỷ lệ hoàn thành cho phòng Nhân sự và ghi nhật ký thay đổi.",en:"Export completion reports for HR and record the change log."}],mistakes:{vi:["Nhập gói SCORM 2004 ở chế độ 1.2 khiến trạng thái hoàn thành không được ghi.","Nhập phần trăm vào ô điểm đạt tính theo điểm, làm học viên đạt hoặc trượt sai.","Sửa trực tiếp cơ sở dữ liệu để đánh dấu hoàn thành khi không có bằng chứng học tập."],en:["Importing a SCORM 2004 package in 1.2 mode so completion status is never stored.","Typing a percentage into a points-based pass mark, so learners pass or fail wrongly.","Editing the database directly to mark completions without any learning evidence."]},career:[{vi:"Chuyên viên hỗ trợ e-learning",en:"E-learning support specialist"},{vi:"Chuyên viên quản trị LMS",en:"LMS administrator"},{vi:"Trưởng nhóm công nghệ đào tạo",en:"Learning technology team lead"},{vi:"Trưởng phòng Đào tạo số",en:"Head of Digital Learning"}],glossary:[{term:"SCORM",vi:"Bộ chuẩn đóng gói và giao tiếp giữa nội dung e-learning với LMS do ADL phát triển.",en:"A set of ADL standards for packaging e-learning content and communicating with the LMS."},{term:"xAPI",vi:"Chuẩn ghi lại trải nghiệm học tập dưới dạng câu lệnh người học - hành động - đối tượng vào LRS.",en:"A standard that records learning as actor-verb-object statements in an LRS."},{term:"imsmanifest.xml",vi:"Tệp mô tả cấu trúc, tài nguyên và phiên bản chuẩn của một gói SCORM.",en:"The file describing a SCORM package's structure, resources and schema version."},{term:"LRS",vi:"Kho bản ghi học tập, nơi lưu trữ và truy vấn các câu lệnh xAPI.",en:"Learning Record Store that stores and serves xAPI statements."},{term:"Grade to pass",vi:"Điểm đạt: ngưỡng điểm tối thiểu để bài kiểm tra được tính là đạt, nhập theo thang điểm của bài.",en:"The minimum score for a quiz to count as passed, entered on the quiz's own point scale."}],quiz:[{q:{vi:"Bài kiểm tra 30 câu, mỗi câu 5 điểm, chính sách đạt 80%. Điểm đạt cần nhập trên LMS là bao nhiêu?",en:"A quiz has 30 questions worth 5 points each and an 80% pass policy. What grade to pass should be entered?"},options:{vi:["80","150","120","30"],en:["80","150","120","30"]},answer:2,explain:{vi:"Tổng điểm 30 x 5 = 150; điểm đạt = 150 x 80% = 120 điểm.",en:"Total is 30 x 5 = 150; grade to pass = 150 x 80% = 120 points."}},{q:{vi:"Gói có schemaversion 2004 4th Edition cần LMS cung cấp đối tượng giao tiếp nào?",en:"A package with schemaversion 2004 4th Edition needs which runtime object from the LMS?"},options:{vi:["API_1484_11","API","Điểm cuối LRS","Liên kết khởi chạy LTI"],en:["API_1484_11","API","LRS endpoint","LTI launch link"]},answer:0,explain:{vi:"SCORM 2004 dùng đối tượng API_1484_11; đối tượng API là của SCORM 1.2.",en:"SCORM 2004 uses the API_1484_11 object; the API object belongs to SCORM 1.2."}},{q:{vi:"Lãnh đạo yêu cầu đánh dấu hoàn thành hàng loạt khóa an toàn trước đợt thanh tra. Bạn làm gì?",en:"Management asks you to bulk-mark a safety course complete before an inspection. What do you do?"},options:{vi:["Làm ngay vì là chỉ đạo","Đánh dấu một nửa số học viên","Chờ thanh tra xong rồi tính","Từ chối, báo cáo trung thực tiến độ và đề xuất kế hoạch khắc phục có phê duyệt"],en:["Do it because it is an order","Mark half of the learners","Wait until the inspection is over","Refuse, report progress honestly and propose an approved remediation plan"]},answer:3,explain:{vi:"Hồ sơ đào tạo an toàn giả mạo là vi phạm pháp luật và đặt người lao động vào rủi ro; phải trung thực và khắc phục thật.",en:"Faked safety training records break the law and put workers at risk; be honest and fix the real problem."}},{q:{vi:"Chuẩn nào phù hợp để ghi nhận học tập ngoài LMS như mô phỏng hoặc học ngoại tuyến trên thiết bị di động?",en:"Which standard suits tracking learning outside the LMS, such as simulations or offline mobile learning?"},options:{vi:["SCORM 1.2","xAPI","HTML 4","FTP"],en:["SCORM 1.2","xAPI","HTML 4","FTP"]},answer:1,explain:{vi:"xAPI ghi câu lệnh học tập từ nhiều nguồn vào LRS, không phụ thuộc trình duyệt và phiên LMS.",en:"xAPI records statements from many sources into an LRS, independent of the browser and LMS session."}}],tools_en:["LMS platforms (Moodle, Canvas)","SCORM/xAPI package testing tools","Learning record store (LRS)","E-learning authoring tools","SQL and BI reporting tools","Browser developer tools"]}}}),n.JobLabContentClusters=(n.JobLabContentClusters||[]).concat(11)})(window.KKR);
